import { State, AppRegistration, InstanceID, Fdc3ApiVersion } from "./AppRegistration"
import {
  ChannelState,
  ChannelType,
  ContextListenerRegistration,
  PrivateChannelEventListener,
  DesktopAgentEventListener,
  IntentListenerRegistration,
  FDC3ServerInstance,
  HeartbeatActivityEvent,
  HandlersByVersion,
  StoredContext,
  StoredContextMetadata,
} from "./FDC3ServerInstance"
import { AppIdentifier, AppIntent } from "@finos/fdc3-standard"
import { Context } from "@finos/fdc3-context"
import { MessageHandler } from "./handlers/MessageHandler"
import { Directory } from "./directory/DirectoryInterface"
import { PendingApp } from "./PendingApp"
import {
  ChannelChangedServerInstanceEvent,
  FDC3ServerInstanceEvent,
  PrivateChannelDisconnectServerInstanceEvent,
  ShutdownServerInstanceEvent,
} from "./FDC3ServerInstanceEvents"
import { ReceivableMessage } from "./AppRegistration"

/**
 * Abstract base class for ServerContext implementations.
 * Contains all common state management logic for channels, listeners, and pending operations.
 */
export abstract class AbstractFDC3ServerInstance implements FDC3ServerInstance {
  protected readonly handlersByVersion: HandlersByVersion

  constructor(handlersByVersion: HandlersByVersion, channels: ChannelState[]) {
    this.handlersByVersion = handlersByVersion
    this.channelStates = channels
  }

  /** All handlers across versions (for shutdown / event fan-out). */
  protected allHandlers(): MessageHandler[] {
    return [...this.handlersByVersion["2.2"], ...this.handlersByVersion["3.0"]]
  }

  protected handlersFor(version: Fdc3ApiVersion | undefined): MessageHandler[] {
    return this.handlersByVersion[version ?? "2.2"] ?? this.handlersByVersion["2.2"]
  }

  // State management fields
  protected contextListeners: ContextListenerRegistration[] = []
  protected privateChannelEventListeners: PrivateChannelEventListener[] = []
  protected desktopAgentEventListeners: DesktopAgentEventListener[] = []
  protected channelStates: ChannelState[]
  protected currentChannels: { [instanceId: string]: ChannelState } = {}
  protected intentListeners: IntentListenerRegistration[] = []
  protected pendingResolutions: Map<string, AppIdentifier> = new Map()
  protected pendingApps: Map<InstanceID, PendingApp> = new Map()

  // Abstract methods that must be implemented by subclasses
  abstract createUUID(): string
  abstract post(message: object, to: InstanceID): Promise<void>
  abstract getInstanceDetails(uuid: InstanceID): AppRegistration | undefined
  abstract setInstanceDetails(uuid: InstanceID, meta: AppRegistration): void
  abstract open(appId: string): Promise<InstanceID>
  abstract close(instanceId: InstanceID): Promise<void>
  abstract getConnectedApps(): Promise<AppRegistration[]>
  abstract isAppConnected(app: InstanceID): Promise<boolean>
  abstract setAppState(app: InstanceID, newState: State): Promise<void>
  abstract getAllApps(): Promise<AppRegistration[]>
  abstract log(message: string): void
  abstract provider(): string
  abstract providerVersion(): string
  abstract fdc3Version(): string
  abstract narrowIntents(
    raiser: AppIdentifier,
    appIntents: AppIntent[],
    context: Context,
  ): Promise<AppIntent[]>
  abstract getDirectory(): Directory

  // Heartbeat activity handling
  async heartbeatActivity(
    instanceId: InstanceID,
    event: HeartbeatActivityEvent,
  ): Promise<void> {
    switch (event) {
      case HeartbeatActivityEvent.ConnectedResponding:
        await this.setAppState(instanceId, State.Connected)
        break
      case HeartbeatActivityEvent.NotRespondingAfterDisconnectTime:
        await this.setAppState(instanceId, State.NotResponding)
        break
      case HeartbeatActivityEvent.NotRespondingAfterDeadTime:
        await this.setAppState(instanceId, State.Terminated)
        break
    }
  }

  // Channel state management methods
  getChannelStates(): ChannelState[] {
    return this.channelStates
  }

  addChannelState(channel: ChannelState): void {
    this.channelStates.push(channel)
  }

  getChannelById(channelId: string | null): ChannelState | null {
    if (channelId == null) {
      return null
    }
    return this.channelStates.find((c) => c.id == channelId) ?? null
  }

  updateChannelContext(
    channelId: string,
    context: Context,
    metadata: StoredContextMetadata,
  ): void {
    const cs = this.getChannelById(channelId)
    if (cs) {
      cs.context = cs.context.filter((c) => c.context.type != context.type)
      const stored: StoredContext = { context, metadata }
      cs.context.unshift(stored)
    }
  }

  clearChannelContext(channelId: string, contextType: string | null): void {
    const cs = this.getChannelById(channelId)
    if (cs) {
      cs.context = contextType
        ? cs.context.filter((c) => c.context.type !== contextType)
        : []
    }
  }

  // Current channel tracking methods
  getCurrentChannel(instanceId: InstanceID): ChannelState | null {
    return this.currentChannels[instanceId] ?? null
  }

  setCurrentChannel(
    instanceId: InstanceID,
    channel: ChannelState | null,
  ): void {
    if (channel === null) {
      delete this.currentChannels[instanceId]
    } else {
      this.currentChannels[instanceId] = channel
    }
    const event = new ChannelChangedServerInstanceEvent(
      instanceId,
      channel?.id ?? null,
    )
    this.notifyEventHandlers(event)
  }

  notifyEventHandlers(event: FDC3ServerInstanceEvent): void {
    this.allHandlers().forEach((handler) => handler.handleEvent(event, this))
  }

  // Context listener management methods
  getContextListeners(): ContextListenerRegistration[] {
    return this.contextListeners
  }

  addContextListener(listener: ContextListenerRegistration): void {
    this.contextListeners.push(listener)
  }

  removeContextListener(listenerUuid: string, instanceId: InstanceID) {
    const i = this.contextListeners.findIndex(
      (r) => r.listenerUuid == listenerUuid && r.instanceId == instanceId,
    )
    if (i > -1) {
      this.contextListeners.splice(i, 1)
    }
  }

  removeContextListenersByInstance(instanceId: InstanceID) {
    const removed = this.contextListeners.filter(
      (r) => r.instanceId == instanceId,
    )
    this.contextListeners = this.contextListeners.filter(
      (listener) => listener.instanceId !== instanceId,
    )
    return removed
  }

  // Private channel event listener management methods
  getPrivateChannelEventListeners(): PrivateChannelEventListener[] {
    return this.privateChannelEventListeners
  }

  addPrivateChannelEventListener(listener: PrivateChannelEventListener): void {
    this.privateChannelEventListeners.push(listener)
  }

  removePrivateChannelEventListener(listenerUuid: string): boolean {
    const i = this.privateChannelEventListeners.findIndex(
      (r) => r.listenerUuid == listenerUuid,
    )
    if (i > -1) {
      this.privateChannelEventListeners.splice(i, 1)
      return true
    }
    return false
  }

  removePrivateChannelEventListenersByInstance(
    instanceId: InstanceID,
  ): PrivateChannelEventListener[] {
    const removed = this.privateChannelEventListeners.filter(
      (listener) => listener.instanceId == instanceId,
    )
    this.privateChannelEventListeners =
      this.privateChannelEventListeners.filter(
        (listener) => listener.instanceId !== instanceId,
      )
    return removed
  }

  getDesktopAgentEventListeners(): DesktopAgentEventListener[] {
    return this.desktopAgentEventListeners
  }

  addDesktopAgentEventListener(listener: DesktopAgentEventListener): void {
    this.desktopAgentEventListeners.push(listener)
  }

  removeDesktopAgentEventListener(listenerUuid: string): boolean {
    const i = this.desktopAgentEventListeners.findIndex(
      (r) => r.listenerUuid == listenerUuid,
    )
    if (i > -1) {
      this.desktopAgentEventListeners.splice(i, 1)
      return true
    }
    return false
  }

  removeDesktopAgentEventListenersByInstance(
    instanceId: InstanceID,
  ): DesktopAgentEventListener[] {
    const removed = this.desktopAgentEventListeners.filter(
      (listener) => listener.instanceId == instanceId,
    )
    this.desktopAgentEventListeners = this.desktopAgentEventListeners.filter(
      (listener) => listener.instanceId !== instanceId,
    )
    return removed
  }

  // Intent listener management methods
  getIntentListeners(): IntentListenerRegistration[] {
    return this.intentListeners
  }

  addIntentListener(listener: IntentListenerRegistration): void {
    this.intentListeners.push(listener)
  }

  removeIntentListener(listenerUUID: string): boolean {
    const i = this.intentListeners.findIndex(
      (r) => r.listenerUUID == listenerUUID,
    )
    if (i > -1) {
      this.intentListeners.splice(i, 1)
      return true
    }
    return false
  }

  removeIntentListenersByInstance(
    instanceId: InstanceID,
  ): IntentListenerRegistration[] {
    const removed = this.intentListeners.filter(
      (r) => r.instanceId == instanceId,
    )
    this.intentListeners = this.intentListeners.filter(
      (listener) => listener.instanceId !== instanceId,
    )
    return removed
  }

  // Pending intent resolution management methods
  getPendingResolution(requestUuid: string): AppIdentifier | undefined {
    return this.pendingResolutions.get(requestUuid)
  }

  addPendingResolution(
    requestUuid: string,
    appIdentifier: AppIdentifier,
  ): void {
    this.pendingResolutions.set(requestUuid, appIdentifier)
  }

  removePendingResolution(requestUuid: string): boolean {
    return this.pendingResolutions.delete(requestUuid)
  }

  removePendingResolutionsByInstance(instanceId: InstanceID): void {
    this.pendingResolutions.forEach((val, key) => {
      if (val.instanceId === instanceId) {
        this.pendingResolutions.delete(key)
      }
    })
  }

  // Pending app management methods
  getPendingApp(instanceId: InstanceID): PendingApp | undefined {
    return this.pendingApps.get(instanceId)
  }

  setPendingApp(instanceId: InstanceID, pendingApp: PendingApp): void {
    this.pendingApps.set(instanceId, pendingApp)
  }

  removePendingApp(instanceId: InstanceID): boolean {
    return this.pendingApps.delete(instanceId)
  }

  async receive(message: ReceivableMessage, from: InstanceID): Promise<void> {
    const details = this.getInstanceDetails(from)
    const handlers = this.handlersFor(details?.fdc3Version)
    await Promise.all(
      handlers.map((handler) => handler.accept(message, this, from)),
    )
  }

  async cleanupApp(instanceId: InstanceID): Promise<void> {
    // Get context listeners for this instance before removing them
    const contextListenersToRemove = this.contextListeners.filter(
      (l) => l.instanceId === instanceId,
    )

    // Find private channels that need disconnect events
    const privateChannelsToDisconnect = new Set<string>()
    contextListenersToRemove
      .filter(
        (u) => this.getChannelById(u.channelId)?.type === ChannelType.private,
      )
      .forEach((u) => {
        if (u.channelId) {
          privateChannelsToDisconnect.add(u.channelId)
        }
      })

    // Fire disconnect events for private channels
    privateChannelsToDisconnect.forEach((channelId) => {
      const disconnectEvent = new PrivateChannelDisconnectServerInstanceEvent(
        instanceId,
        channelId,
      )
      this.notifyEventHandlers(disconnectEvent)
    })

    // Clean up state entries
    this.removeContextListenersByInstance(instanceId)
    this.removePrivateChannelEventListenersByInstance(instanceId)
    this.removeDesktopAgentEventListenersByInstance(instanceId)
    this.removeIntentListenersByInstance(instanceId)
    this.removePendingResolutionsByInstance(instanceId)
    // Note: Don't remove pending apps as they may still be opening
  }

  async shutdown(): Promise<void> {
    const shutdownEvent = new ShutdownServerInstanceEvent()
    this.notifyEventHandlers(shutdownEvent)
  }
}

import { InstanceID } from "./AppRegistration"

/**
 * These are events not coming from another FDC3 application, but from the
 * FDC3ServerInstance itself.
 */
export interface FDC3ServerInstanceEvent {
  type: string
}

/**
 * Used when the FDC3ServerInstance wants to notify the handler that the private channel has been disconnected.
 */
export class PrivateChannelDisconnectServerInstanceEvent
  implements FDC3ServerInstanceEvent
{
  public type: string

  constructor(
    public instanceId: InstanceID,
    public channelId: string,
  ) {
    this.type = "privateChannelDisconnect"
  }
}

/**
 * Used when the FDC3ServerInstance wants to notify the handler that the current channel has changed.
 */
export class ChannelChangedServerInstanceEvent
  implements FDC3ServerInstanceEvent
{
  public type: string

  constructor(
    public instanceId: InstanceID,
    public channelId: string | null,
  ) {
    this.type = "channelChanged"
  }
}

/**
 * Used when the FDC3ServerInstance is shutting down
 */
export class ShutdownServerInstanceEvent implements FDC3ServerInstanceEvent {
  public type: string

  constructor() {
    this.type = "shutdown"
  }
}

import { LogFunction, MessageHandler } from "../MessageHandler"
import {
  ChannelState,
  ChannelType,
  ContextListenerRegistration,
  DesktopAgentEventListener,
  PrivateChannelEventListener,
  FDC3ServerInstance,
} from "../../FDC3ServerInstance"
import {
  InstanceID,
  ReceivableMessage,
  Fdc3ApiVersion,
} from "../../AppRegistration"
import {
  AppIdentifier,
  ChannelError,
  PrivateChannelEventTypes,
} from "@finos/fdc3-standard"
import { successResponse, errorResponse, FullAppIdentifier } from "./support"
import {
  AddContextListenerRequest,
  AddEventListenerRequest,
  AgentResponseMessage,
  AppRequestMessage,
  BroadcastRequest,
  ChannelChangedEvent,
  ContextListenerUnsubscribeRequest,
  CreatePrivateChannelRequest,
  EventListenerUnsubscribeRequest,
  GetCurrentChannelRequest,
  GetCurrentContextRequest,
  GetOrCreateChannelRequest,
  GetUserChannelsRequest,
  JoinUserChannelRequest,
  LeaveCurrentChannelRequest,
  PrivateChannelAddEventListenerRequest,
  PrivateChannelDisconnectRequest,
  PrivateChannelOnAddContextListenerEvent,
  PrivateChannelOnDisconnectEvent,
  PrivateChannelOnUnsubscribeEvent,
  PrivateChannelUnsubscribeEventListenerRequest,
} from "@finos/fdc3-schema/dist/generated/api/BrowserTypes"
import {
  PrivateChannelDisconnectServerInstanceEvent,
  FDC3ServerInstanceEvent,
  ChannelChangedServerInstanceEvent,
} from "../../FDC3ServerInstanceEvents"

type PrivateChannelEvents =
  | PrivateChannelOnAddContextListenerEvent
  | PrivateChannelOnUnsubscribeEvent
  | PrivateChannelOnDisconnectEvent

function onlyUniqueAppIds(
  value: AppIdentifier,
  index: number,
  self: AppIdentifier[],
) {
  const fi = self.findIndex((v) => v.instanceId === value.instanceId)
  return fi === index
}

/** Matches a listener's contextType (null = all, string, or string[]) against a context type. */
function matchesContextType(
  listenerType: string | string[] | null,
  contextType: string,
): boolean {
  if (listenerType == null) {
    return true
  }
  if (Array.isArray(listenerType)) {
    return listenerType.includes(contextType)
  }
  return listenerType == contextType
}

/** For 2.2 private-channel events: singular contextType only. */
function toSingularContextType(
  contextType?: string | string[] | null,
): string | null | undefined {
  if (Array.isArray(contextType)) {
    return contextType.length === 1 ? contextType[0] : null
  }
  return contextType
}

export class BroadcastHandler implements MessageHandler {
  private readonly log: LogFunction
  private readonly apiVersion: Fdc3ApiVersion = "2.2"

  constructor(log?: LogFunction) {
    this.log = log ?? (() => {})
  }

  shutdown(): void {}

  private matchesApiVersion(sc: FDC3ServerInstance, instanceId: string): boolean {
    const version = sc.getInstanceDetails(instanceId)?.fdc3Version ?? "2.2"
    return version === this.apiVersion
  }

  getCurrentChannel(
    from: FullAppIdentifier,
    sc: FDC3ServerInstance,
  ): ChannelState | null {
    return sc.getCurrentChannel(from.instanceId)
  }

  fireChannelChangedEvent(
    channelId: string | null,
    sc: FDC3ServerInstance,
    instanceId: string,
  ) {
    const hasChannelChangedListener = sc
      .getDesktopAgentEventListeners()
      .some(
        (listener) =>
          listener.instanceId === instanceId &&
          (listener.eventType === null ||
            listener.eventType === "USER_CHANNEL_CHANGED"),
      )
    if (!hasChannelChangedListener) {
      return
    }

    const event: ChannelChangedEvent = {
      meta: {
        eventUuid: sc.createUUID(),
        timestamp: new Date(),
      },
      type: "channelChangedEvent",
      payload: {
        newChannelId: channelId,
      },
    }

    sc.post(event, instanceId)
  }

  convertChannelTypeToString(type: ChannelType): string {
    switch (type) {
      case ChannelType.app:
        return "app"
      case ChannelType.user:
        return "user"
      case ChannelType.private:
        return "private"
    }
  }

  async accept(
    msg: ReceivableMessage,
    sc: FDC3ServerInstance,
    uuid: InstanceID,
  ) {
    const from = sc.getInstanceDetails(uuid)

    if (from == null) {
      // this handler only deals with connected apps
      return
    }

    this.log(`BroadcastHandler: accept called with msg: ${JSON.stringify(msg)}`)

    try {
      switch (msg.type as string | null) {
        // app channels registration
        case "getOrCreateChannelRequest":
          return this.handleGetOrCreateRequest(
            msg as unknown as GetOrCreateChannelRequest,
            sc,
            from,
          )

        // user channel management
        case "getUserChannelsRequest":
          return this.handleGetUserChannelsRequest(
            msg as unknown as GetUserChannelsRequest,
            sc,
            from,
          )
        case "leaveCurrentChannelRequest":
          return this.handleLeaveCurrentChannelRequest(
            msg as unknown as LeaveCurrentChannelRequest,
            sc,
            from,
          )
        case "joinUserChannelRequest":
          return this.handleJoinUserChannelRequest(
            msg as unknown as JoinUserChannelRequest,
            sc,
            from,
          )
        case "getCurrentChannelRequest":
          return this.handleGetCurrentChannelRequest(
            msg as unknown as GetCurrentChannelRequest,
            sc,
            from,
          )

        // general broadcast
        case "broadcastRequest":
          return this.handleBroadcastRequest(
            msg as unknown as BroadcastRequest,
            sc,
            from,
          )

        // context listeners
        case "addContextListenerRequest":
          return this.handleAddContextListenerRequest(
            msg as unknown as AddContextListenerRequest,
            sc,
            from,
          )
        case "contextListenerUnsubscribeRequest":
          return this.handleContextListenerUnsubscribeRequest(
            msg as unknown as ContextListenerUnsubscribeRequest,
            sc,
            from,
          )

        // private channels create/disconnect
        case "createPrivateChannelRequest":
          return this.handleCreatePrivateChannelRequest(
            msg as unknown as CreatePrivateChannelRequest,
            sc,
            from,
          )
        case "privateChannelDisconnectRequest":
          return this.handlePrivateChannelDisconnectRequest(
            msg as unknown as PrivateChannelDisconnectRequest,
            sc,
            from,
          )

        // private channel event listeners
        case "privateChannelAddEventListenerRequest":
          return this.handlePrivateChannelAddEventListenerRequest(
            msg as unknown as PrivateChannelAddEventListenerRequest,
            from,
            sc,
          )
        case "privateChannelUnsubscribeEventListenerRequest":
          return this.handlePrivateChannelUnsubscribeEventListenerRequest(
            msg as unknown as PrivateChannelUnsubscribeEventListenerRequest,
            sc,
            from,
          )

        // handling state synchronization of channels
        case "getCurrentContextRequest":
          return this.handleGetCurrentContextRequest(
            msg as unknown as GetCurrentContextRequest,
            sc,
            from,
          )

        // TODO: move this out when we no longer handle just channel-based events.
        case "addEventListenerRequest":
          return this.handleAddEventListenerRequest(
            msg as unknown as AddEventListenerRequest,
            sc,
            from,
          )
        case "eventListenerUnsubscribeRequest":
          return this.handleEventListenerUnsubscribeRequest(
            msg as unknown as EventListenerUnsubscribeRequest,
            sc,
            from,
          )
      }
    } catch (e) {
      const responseType = (msg.type as string).replace(
        new RegExp("Request$"),
        "Response",
      )
      errorResponse(
        sc,
        msg as unknown as AppRequestMessage,
        from,
        (e as Error).message ?? e,
        responseType as AgentResponseMessage["type"],
      )
    }
  }

  handleAddEventListenerRequest(
    arg0: AddEventListenerRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const lr: DesktopAgentEventListener = {
      appId: from.appId,
      instanceId: from.instanceId ?? "no-instance-id",
      listenerUuid: sc.createUUID(),
      eventType: arg0.payload.type ?? null,
      channelId: null,
    }

    sc.addDesktopAgentEventListener(lr)
    successResponse(
      sc,
      arg0,
      from,
      { listenerUUID: lr.listenerUuid },
      "addEventListenerResponse",
    )
  }

  handleEventListenerUnsubscribeRequest(
    arg0: EventListenerUnsubscribeRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const removed = sc.removeDesktopAgentEventListener(
      arg0.payload.listenerUUID,
    )
    if (removed) {
      successResponse(sc, arg0, from, {}, "eventListenerUnsubscribeResponse")
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        "ListenerNotFound",
        "eventListenerUnsubscribeResponse",
      )
    }
  }

  handleCreatePrivateChannelRequest(
    arg0: CreatePrivateChannelRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const id = sc.createUUID()
    sc.addChannelState({
      id,
      type: ChannelType.private,
      context: [],
      displayMetadata: {},
    })

    successResponse(
      sc,
      arg0,
      from,
      {
        privateChannel: {
          id,
          type: this.convertChannelTypeToString(ChannelType.private),
        },
      },
      "createPrivateChannelResponse",
    )
  }

  handleGetCurrentContextRequest(
    arg0: GetCurrentContextRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const channel = sc.getChannelById(arg0.payload.channelId)
    const type = arg0.payload.contextType

    if (channel) {
      const stored = type
        ? (channel.context.find((c) => c.context.type == type) ?? null)
        : (channel.context[0] ?? null)
      successResponse(
        sc,
        arg0,
        from,
        { context: stored?.context ?? null },
        "getCurrentContextResponse",
      )
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        ChannelError.NoChannelFound,
        "getCurrentContextResponse",
      )
    }
  }

  handlePrivateChannelUnsubscribeEventListenerRequest(
    arg0: PrivateChannelUnsubscribeEventListenerRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const removed = sc.removePrivateChannelEventListener(
      arg0.payload.listenerUUID,
    )
    if (removed) {
      successResponse(
        sc,
        arg0,
        from,
        {},
        "privateChannelUnsubscribeEventListenerResponse",
      )
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        "ListenerNotFound",
        "privateChannelUnsubscribeEventListenerResponse",
      )
    }
  }

  handlePrivateChannelDisconnectRequest(
    arg0: PrivateChannelDisconnectRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const toUnsubscribe = sc
      .getContextListeners()
      .filter((r) => r.appId == from.appId && r.instanceId == from.instanceId)
      .filter((r) => r.channelId == arg0.payload.channelId)

    toUnsubscribe.forEach((u) => {
      this.invokePrivateChannelEventListeners(
        arg0.payload.channelId,
        "unsubscribe",
        "privateChannelOnUnsubscribeEvent",
        sc,
        u.contextType,
      )
    })

    // Remove the listeners
    toUnsubscribe.forEach((u) => {
      sc.removeContextListener(u.listenerUuid, u.instanceId)
    })

    this.invokePrivateChannelEventListeners(
      arg0.payload.channelId,
      "disconnect",
      "privateChannelOnDisconnectEvent",
      sc,
    )
    successResponse(sc, arg0, from, {}, "privateChannelDisconnectResponse")
  }

  handleContextListenerUnsubscribeRequest(
    arg0: ContextListenerUnsubscribeRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const rl = sc
      .getContextListeners()
      .find(
        (r) =>
          r.listenerUuid == arg0.payload.listenerUUID &&
          r.instanceId == from.instanceId,
      )

    if (rl) {
      const channel = sc.getChannelById(rl.channelId)
      this.invokePrivateChannelEventListeners(
        channel?.id ?? null,
        "unsubscribe",
        "privateChannelOnUnsubscribeEvent",
        sc,
        rl.contextType,
      )
      sc.removeContextListener(arg0.payload.listenerUUID, from.instanceId)
      successResponse(sc, arg0, from, {}, "contextListenerUnsubscribeResponse")
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        "ListenerNotFound",
        "contextListenerUnsubscribeResponse",
      )
    }
  }

  handleAddContextListenerRequest(
    arg0: AddContextListenerRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    let channelId = null

    if (arg0.payload?.channelId) {
      // if channelId is provided, we need to check if it exists
      const channel = sc.getChannelById(arg0.payload?.channelId)

      if (channel == null) {
        errorResponse(
          sc,
          arg0,
          from,
          ChannelError.NoChannelFound,
          "addContextListenerResponse",
        )
        return
      } else {
        channelId = channel.id
      }
    }

    const lr: ContextListenerRegistration = {
      appId: from.appId,
      instanceId: from.instanceId ?? "no-instance-id",
      channelId: channelId,
      listenerUuid: sc.createUUID(),
      contextType: arg0.payload.contextType,
    }

    sc.addContextListener(lr)
    this.invokePrivateChannelEventListeners(
      channelId,
      "addContextListener",
      "privateChannelOnAddContextListenerEvent",
      sc,
      arg0.payload.contextType ?? undefined,
    )
    successResponse(
      sc,
      arg0,
      from,
      { listenerUUID: lr.listenerUuid },
      "addContextListenerResponse",
    )
  }

  handleBroadcastRequest(
    arg0: BroadcastRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const matchesExactChannel = (r: ContextListenerRegistration) => {
      return r.channelId == arg0.payload.channelId
    }

    const matchesUserChannel = (r: ContextListenerRegistration) => {
      const uc = sc.getCurrentChannel(r.instanceId)
      const ucId = uc ? uc.id : null
      return r.channelId == null && ucId == arg0.payload.channelId
    }

    const matchingListeners = sc
      .getContextListeners()
      .filter((r) => matchesExactChannel(r) || matchesUserChannel(r))
      .filter((r) => matchesContextType(r.contextType, arg0.payload.context.type))

    const matchingApps: FullAppIdentifier[] = matchingListeners
      .map((r) => {
        return { appId: r.appId, instanceId: r.instanceId }
      })
      .filter(onlyUniqueAppIds)

    matchingApps.forEach((app) => {
      sc.post(
        {
          meta: {
            eventUuid: sc.createUUID(),
            timestamp: new Date(),
          },
          type: "broadcastEvent",
          payload: {
            channelId: arg0.payload.channelId,
            context: arg0.payload.context,
          },
        },
        app.instanceId,
      )
    })

    sc.updateChannelContext(arg0.payload.channelId, arg0.payload.context, {
      source: from,
    })
    successResponse(sc, arg0, from, {}, "broadcastResponse")
  }

  handleGetCurrentChannelRequest(
    arg0: GetCurrentChannelRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const currentChannel = this.getCurrentChannel(from, sc)
    if (currentChannel) {
      successResponse(
        sc,
        arg0,
        from,
        {
          channel: {
            id: currentChannel.id,
            type: this.convertChannelTypeToString(currentChannel.type),
            displayMetadata: currentChannel.displayMetadata,
          },
        },
        "getCurrentChannelResponse",
      )
    } else {
      successResponse(
        sc,
        arg0,
        from,
        { channel: null },
        "getCurrentChannelResponse",
      )
    }
  }

  handleJoinUserChannelRequest(
    arg0: JoinUserChannelRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    // check it's a user channel
    const newChannel = sc.getChannelById(arg0.payload.channelId)
    if (newChannel == null || newChannel.type != ChannelType.user) {
      return errorResponse(
        sc,
        arg0,
        from,
        ChannelError.NoChannelFound,
        "joinUserChannelResponse",
      )
    }

    // join it.
    const instanceId = from.instanceId ?? "no-instance-id"
    sc.setCurrentChannel(instanceId, newChannel)
    successResponse(sc, arg0, from, {}, "joinUserChannelResponse")
  }

  handleLeaveCurrentChannelRequest(
    arg0: LeaveCurrentChannelRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const instanceId = from.instanceId ?? "no-instance-id"
    sc.setCurrentChannel(instanceId, null)
    successResponse(sc, arg0, from, {}, "leaveCurrentChannelResponse")
  }

  handleGetOrCreateRequest(
    arg0: GetOrCreateChannelRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const id = arg0.payload.channelId
    let channel = sc.getChannelById(id)

    if (!channel) {
      channel = {
        id: id,
        type: ChannelType.app,
        context: [],
        displayMetadata: {},
      }
      sc.addChannelState(channel)
    }

    if (channel.type != ChannelType.app) {
      errorResponse(
        sc,
        arg0,
        from,
        ChannelError.AccessDenied,
        "getOrCreateChannelResponse",
      )
    } else {
      successResponse(
        sc,
        arg0,
        from,
        { channel: { id: channel.id, type: channel.type } },
        "getOrCreateChannelResponse",
      )
    }
  }

  handleGetUserChannelsRequest(
    arg0: GetUserChannelsRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const userChannels = sc
      .getChannelStates()
      .filter((c) => c.type == ChannelType.user)
    successResponse(
      sc,
      arg0,
      from,
      {
        userChannels: userChannels.map((c) => ({
          id: c.id,
          type: this.convertChannelTypeToString(c.type),
          displayMetadata: c.displayMetadata,
        })),
      },
      "getUserChannelsResponse",
    )
  }

  handlePrivateChannelAddEventListenerRequest(
    arg0: PrivateChannelAddEventListenerRequest,
    from: FullAppIdentifier,
    sc: FDC3ServerInstance,
  ) {
    const channel = sc.getChannelById(arg0.payload.privateChannelId)

    if (channel == null || channel.type != ChannelType.private) {
      errorResponse(
        sc,
        arg0,
        from,
        ChannelError.NoChannelFound,
        "privateChannelAddEventListenerResponse",
      )
    } else {
      const el = {
        appId: from.appId,
        instanceId: from.instanceId,
        channelId: arg0.payload.privateChannelId,
        eventType: arg0.payload.listenerType,
        listenerUuid: sc.createUUID(),
      } as PrivateChannelEventListener
      sc.addPrivateChannelEventListener(el)
      successResponse(
        sc,
        arg0,
        from,
        { listenerUUID: el.listenerUuid },
        "privateChannelAddEventListenerResponse",
      )
    }
  }

  invokePrivateChannelEventListeners(
    privateChannelId: string | null,
    eventType: PrivateChannelEventTypes,
    messageType:
      | "privateChannelOnAddContextListenerEvent"
      | "privateChannelOnUnsubscribeEvent"
      | "privateChannelOnDisconnectEvent",
    sc: FDC3ServerInstance,
    contextType?: string | string[] | null,
  ) {
    if (privateChannelId) {
      const msg: PrivateChannelEvents = {
        type: messageType,
        meta: {
          eventUuid: sc.createUUID(),
          timestamp: new Date(),
        },
        payload: {
          privateChannelId,
          contextType: toSingularContextType(contextType),
        },
      } as PrivateChannelEvents //Typescript doesn't like comparing an object with a union property (messageType) with a union of object types

      this.log("invokePrivateChannelEventListeners msg: ", msg)
      sc.getPrivateChannelEventListeners()
        .filter(
          (listener) =>
            listener.channelId == privateChannelId &&
            (listener.eventType == eventType || listener.eventType == null),
        )
        .filter((listener) => this.matchesApiVersion(sc, listener.instanceId))
        .filter(onlyUniqueAppIds)
        .forEach((e) => {
          this.log(
            `invokePrivateChannelEventListeners: posting to instance ${e.instanceId}`,
          )
          sc.post(msg, e.instanceId)
        })
    }
  }

  async handleEvent(
    e: FDC3ServerInstanceEvent,
    sc: FDC3ServerInstance,
  ): Promise<void> {
    if (e.type === "privateChannelDisconnect") {
      const event = e as PrivateChannelDisconnectServerInstanceEvent

      const privateChannelsToDisconnect = new Set<string>()

      sc.getContextListeners()
        .filter((l) => l.channelId == event.channelId)
        .filter((l) => this.matchesApiVersion(sc, l.instanceId))
        .forEach((l) => {
          this.invokePrivateChannelEventListeners(
            l.channelId,
            "unsubscribe",
            "privateChannelOnUnsubscribeEvent",
            sc,
            l.contextType,
          )
          if (l.channelId) {
            privateChannelsToDisconnect.add(l.channelId)
          }
        })

      privateChannelsToDisconnect.forEach((chan) => {
        this.invokePrivateChannelEventListeners(
          chan,
          "disconnect",
          "privateChannelOnDisconnectEvent",
          sc,
        )
      })
    } else if (e.type === "channelChanged") {
      const event = e as ChannelChangedServerInstanceEvent
      if (!this.matchesApiVersion(sc, event.instanceId)) {
        return
      }
      return this.fireChannelChangedEvent(event.channelId, sc, event.instanceId)
    }
  }
}

import {
  AgentResponseMessage,
  AppRequestMessage,
} from "@finos/fdc3-schema/dist/generated/api/BrowserTypes"
import { AppIdentifier } from "@finos/fdc3-standard"
import { FDC3ServerInstance } from "../../FDC3ServerInstance"

/** Interface representing a full specified app identifier (instanceId is optional in the API type). */
export interface FullAppIdentifier {
  readonly appId: string
  readonly instanceId: string
}

export function isFullAppIdentifier(
  identifier: AppIdentifier | FullAppIdentifier,
): identifier is FullAppIdentifier {
  const typedIdentifier = identifier as FullAppIdentifier
  return (
    typedIdentifier.instanceId !== undefined &&
    typedIdentifier.appId !== undefined
  )
}

export function successResponse(
  sc: FDC3ServerInstance,
  request: AppRequestMessage,
  to: FullAppIdentifier,
  payload: AgentResponseMessage["payload"],
  type: AgentResponseMessage["type"],
) {
  return successResponseId(sc, request.meta.requestUuid, to, payload, type)
}

export function errorResponse(
  sc: FDC3ServerInstance,
  request: AppRequestMessage,
  to: FullAppIdentifier,
  error: string,
  type: AgentResponseMessage["type"],
) {
  return errorResponseId(sc, request.meta.requestUuid, to, error, type)
}

export function successResponseId(
  sc: FDC3ServerInstance,
  requestId: string,
  to: FullAppIdentifier,
  payload: AgentResponseMessage["payload"],
  type: AgentResponseMessage["type"],
) {
  const msg = {
    meta: {
      responseUuid: sc.createUUID(),
      requestUuid: requestId,
      timestamp: new Date(),
    },
    type,
    payload,
  }
  sc.post(msg, to.instanceId!)
}

export function errorResponseId(
  sc: FDC3ServerInstance,
  requestId: string,
  to: FullAppIdentifier,
  error: string,
  type: AgentResponseMessage["type"],
) {
  sc.post(
    {
      meta: {
        responseUuid: sc.createUUID(),
        requestUuid: requestId,
        timestamp: new Date(),
      },
      type,
      payload: {
        error,
      },
    } as AgentResponseMessage,
    to.instanceId!,
  )
}

import { LogFunction, MessageHandler } from "../MessageHandler"
import {
  FDC3ServerInstance,
  IntentListenerRegistration,
} from "../../FDC3ServerInstance"
import { AppRegistration, InstanceID, State, ReceivableMessage } from "../../AppRegistration"
import { DirectoryIntent } from "../../directory/DirectoryInterface"
import { Context } from "@finos/fdc3-context"
import { AppIntent, ResolveError, AppIdentifier } from "@finos/fdc3-standard"
import {
  errorResponse,
  errorResponseId,
  FullAppIdentifier,
  isFullAppIdentifier,
  successResponse,
  successResponseId,
} from "./support"
import {
  IntentEvent,
  FindIntentsByContextRequest,
  FindIntentRequest,
  AddIntentListenerRequest,
  IntentListenerUnsubscribeRequest,
  RaiseIntentRequest,
  RaiseIntentForContextRequest,
  IntentResultRequest,
  AppRequestMessage,
  AgentResponseMessage,
} from "@finos/fdc3-schema/dist/generated/api/BrowserTypes"

type IntentRequest = {
  intent: string
  context: Context
  requestUuid: string
  from: FullAppIdentifier
  type: "raiseIntentResponse" | "raiseIntentForContextResponse"
}

/**
 * Re-writes the request to forward it on to the target application
 */
async function forwardRequest(
  arg0: IntentRequest,
  to: FullAppIdentifier,
  sc: FDC3ServerInstance,
): Promise<void> {
  const out: IntentEvent = {
    type: "intentEvent",
    payload: {
      context: arg0.context,
      intent: arg0.intent,
      originatingApp: {
        appId: arg0.from.appId,
        instanceId: arg0.from.instanceId,
      },
      raiseIntentRequestUuid: arg0.requestUuid,
    },
    meta: {
      eventUuid: sc.createUUID(),
      timestamp: new Date(),
    },
  }

  // register the resolution destination
  sc.addPendingResolution(arg0.requestUuid, arg0.from)
  await sc.post(out, to.instanceId)
  successResponseId(
    sc,
    arg0.requestUuid,
    arg0.from,
    {
      intentResolution: {
        intent: arg0.intent,
        source: { appId: to.appId, instanceId: to.instanceId }, //make sure we're not carrying any excess fields from internal state
      },
    },
    arg0.type,
  )
}

/**
 * A pending intent is one for an app that hasn't registered it's intent listener yet.
 * (Possibly it is being opened)
 *
 * Pending intents wait for that registration and then message the app.
 */
class PendingIntent {
  complete: boolean = false
  r: IntentRequest
  appId: AppIdentifier
  sc: FDC3ServerInstance
  ih: IntentHandler

  constructor(
    r: IntentRequest,
    sc: FDC3ServerInstance,
    ih: IntentHandler,
    appId: AppIdentifier,
  ) {
    this.r = r
    this.appId = appId
    this.sc = sc
    this.ih = ih

    // handle the timeout
    setTimeout(() => {
      if (!this.complete) {
        errorResponseId(
          sc,
          r.requestUuid,
          r.from,
          ResolveError.IntentDeliveryFailed,
          r.type,
        )
        this.ih.pendingIntents.delete(this)
      }
    }, ih.timeoutMs)
  }

  async accept(arg0: IntentListenerRegistration): Promise<void> {
    if (
      arg0.appId == this.appId.appId &&
      arg0.intentName == this.r.intent &&
      (arg0.contextTypes == null ||
        arg0.contextTypes == undefined ||
        arg0.contextTypes.includes(this.r.context.type)) &&
      (arg0.instanceId == this.appId.instanceId ||
        this.appId.instanceId == undefined)
    ) {
      this.complete = true
      this.ih.pendingIntents.delete(this)
      forwardRequest(
        this.r,
        { appId: arg0.appId, instanceId: arg0.instanceId },
        this.sc,
      )
    }
  }
}

export class IntentHandler implements MessageHandler {
  readonly pendingIntents: Set<PendingIntent> = new Set()
  readonly timeoutMs: number
  private readonly log: LogFunction

  constructor(timeoutMs: number, log?: LogFunction) {
    this.timeoutMs = timeoutMs
    this.log = log ?? (() => {})
  }

  shutdown(): void {}

  async narrowIntents(
    raiser: AppIdentifier,
    appIntents: AppIntent[],
    context: Context,
    sc: FDC3ServerInstance,
  ): Promise<AppIntent[]> {
    const out = await sc.narrowIntents(raiser, appIntents, context)
    return out
  }

  async accept(
    msg: ReceivableMessage,
    sc: FDC3ServerInstance,
    uuid: InstanceID,
  ): Promise<void> {
    const from = sc.getInstanceDetails(uuid)

    if (from == null) {
      // this handler only deals with connected apps
      return
    }

    try {
      switch (msg.type as string) {
        // finding intents=
        case "findIntentsByContextRequest":
          return await this.findIntentsByContextRequest(
            msg as unknown as FindIntentsByContextRequest,
            sc,
            from,
          )
        case "findIntentRequest":
          return await this.findIntentRequest(
            msg as unknown as FindIntentRequest,
            sc,
            from,
          )

        // listeners
        case "addIntentListenerRequest":
          return await this.onAddIntentListener(
            msg as unknown as AddIntentListenerRequest,
            sc,
            from,
          )
        case "intentListenerUnsubscribeRequest":
          return await this.onUnsubscribe(
            msg as unknown as IntentListenerUnsubscribeRequest,
            sc,
            from,
          )

        // raising intents and returning results
        case "raiseIntentRequest":
          return await this.raiseIntentRequest(
            msg as unknown as RaiseIntentRequest,
            sc,
            from,
          )
        case "raiseIntentForContextRequest":
          return await this.raiseIntentForContextRequest(
            msg as unknown as RaiseIntentForContextRequest,
            sc,
            from,
          )
        case "intentResultRequest":
          return await this.intentResultRequest(
            msg as unknown as IntentResultRequest,
            sc,
            from,
          )
      }
    } catch (e) {
      const responseType = (msg.type as string).replace(
        new RegExp("Request$"),
        "Response",
      ) as AgentResponseMessage["type"]
      errorResponse(
        sc,
        msg as unknown as AppRequestMessage,
        from,
        (e as Error).message ?? e,
        responseType,
      )
    }
  }

  /**
   * Called when target app handles an intent
   */
  intentResultRequest(
    arg0: IntentResultRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): void | PromiseLike<void> {
    const requestId = arg0.payload.raiseIntentRequestUuid
    const to = sc.getPendingResolution(requestId)
    if (to && to.instanceId) {
      // post the result to the app that raised the intent
      //   if its still connected, otherwise do nothing
      successResponseId(
        sc,
        requestId,
        to as FullAppIdentifier,
        {
          intentResult: arg0.payload.intentResult,
        },
        "raiseIntentResultResponse",
      )

      sc.removePendingResolution(requestId)
    }
    // respond to the app that handled the intent
    successResponse(sc, arg0, from, {}, "intentResultResponse")
  }

  onUnsubscribe(
    arg0: IntentListenerUnsubscribeRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): void {
    const id = arg0.payload.listenerUUID
    const removed = sc.removeIntentListener(id)
    if (removed) {
      successResponse(sc, arg0, from, {}, "intentListenerUnsubscribeResponse")
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        "Non-Existent Listener",
        "intentListenerUnsubscribeResponse",
      )
    }
  }

  onAddIntentListener(
    arg0: AddIntentListenerRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): void {
    const lr: IntentListenerRegistration = {
      appId: from.appId,
      instanceId: from.instanceId,
      intentName: arg0.payload.intent,
      listenerUUID: sc.createUUID(),
    }

    sc.addIntentListener(lr)
    successResponse(
      sc,
      arg0,
      from,
      {
        listenerUUID: lr.listenerUUID,
      },
      "addIntentListenerResponse",
    )

    // see if this intent listener is the destination for any pending intents
    for (const x of this.pendingIntents) {
      x.accept(lr)
      if (x.complete) {
        this.pendingIntents.delete(x)
      }
    }
  }

  hasListener(
    instanceId: string,
    intentName: string,
    sc: FDC3ServerInstance,
    contextType?: string,
  ): boolean {
    return (
      sc
        .getIntentListeners()
        .find(
          (r) =>
            r.instanceId == instanceId &&
            r.intentName == intentName &&
            (contextType == undefined ||
              r.contextTypes == null ||
              r.contextTypes == undefined ||
              r.contextTypes.includes(contextType)),
        ) != null
    )
  }

  async startWithPendingIntent(
    arg0: IntentRequest,
    sc: FDC3ServerInstance,
    target: AppIdentifier,
  ): Promise<void> {
    // app exists but needs starting
    const pi = new PendingIntent(arg0, sc, this, target)
    this.pendingIntents.add(pi)
    sc.open(target.appId).then(() => {
      return undefined
    })
  }

  async raiseIntentRequestToSpecificInstance(
    arg0: IntentRequest[],
    sc: FDC3ServerInstance,
    target: FullAppIdentifier,
  ): Promise<void> {
    if (!(await sc.isAppConnected(target.instanceId))) {
      // instance doesn't exist
      return errorResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        ResolveError.TargetInstanceUnavailable,
        arg0[0].type,
      )
    }

    const requestsWithListeners = arg0.filter((r) =>
      this.hasListener(target.instanceId, r.intent, sc, r.context.type),
    )

    if (requestsWithListeners.length == 0) {
      this.createPendingIntentIfAllowed(arg0[0], sc, target)
    } else {
      // ok, deliver to the current running app.
      return forwardRequest(requestsWithListeners[0], target, sc)
    }
  }

  async createPendingIntentIfAllowed(
    ir: IntentRequest,
    sc: FDC3ServerInstance,
    target: AppIdentifier,
  ) {
    // if this app declares that it supports the intent, we'll create a pending intent
    const matchingIntents: DirectoryIntent[] = sc
      .getDirectory()
      .retrieveIntents(ir.context.type, ir.intent, undefined)
    const declared = matchingIntents.find((i) => i.appId == target.appId)

    if (declared) {
      // maybe listener hasn't been registered yet - create a pending intent
      const pi = new PendingIntent(ir, sc, this, target)
      this.pendingIntents.add(pi)
    } else {
      errorResponseId(
        sc,
        ir.requestUuid,
        ir.from,
        ResolveError.NoAppsFound,
        ir.type,
      )
    }
  }

  async raiseIntentRequestToSpecificAppId(
    arg0: IntentRequest[],
    sc: FDC3ServerInstance,
    target: AppIdentifier,
  ): Promise<void> {
    const appRecords = sc.getDirectory().retrieveAppsById(target.appId)
    if (appRecords.length == 0) {
      return errorResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        ResolveError.TargetAppUnavailable,
        arg0[0].type,
      )
    }

    const convertDirectoryIntentsToAppIntents = (
      intents: DirectoryIntent[],
      appId: string,
    ): AppIntent[] => {
      // group by intent name
      const intentNames = new Set(intents.map((i) => i.intentName))
      return Array.from(intentNames).map((intentName) => {
        const intentsWithName = intents.filter(
          (i) => i.intentName === intentName,
        )
        return {
          intent: { name: intentName, displayName: intentName },
          apps: intentsWithName
            .filter((i) => i.appId === appId)
            .map((i) => ({ appId: i.appId })),
        }
      })
    }

    const intentsAllHaveApps = (appIntents: AppIntent[]): boolean => {
      return appIntents.every((ai) => ai.apps.length > 0)
    }

    // in this version of the method, we always open an app as no
    // specific instance is specified.  But only if the app supports the intent.
    const context: Context = arg0[0].context
    const matchingIntents: DirectoryIntent[] = sc
      .getDirectory()
      .retrieveIntents(context.type, arg0[0].intent, undefined)
    const appIntents = convertDirectoryIntentsToAppIntents(
      matchingIntents,
      target.appId,
    )

    if (appIntents.length == 0) {
      return errorResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        ResolveError.NoAppsFound,
        arg0[0].type,
      )
    }

    if (!intentsAllHaveApps(appIntents)) {
      return errorResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        ResolveError.IntentDeliveryFailed,
        arg0[0].type,
      )
    }

    const narrowedAppIntents = await this.narrowIntents(
      arg0[0].from,
      appIntents,
      context,
      sc,
    )

    if (narrowedAppIntents.length == 1) {
      if (narrowedAppIntents[0].apps.length == 1) {
        // no running instance, single app
        const appRecords = sc.getDirectory().retrieveAppsById(target.appId)
        if (appRecords.length >= 1) {
          const ir: IntentRequest = {
            ...arg0[0],
            intent: narrowedAppIntents[0].intent.name,
          }
          return this.startWithPendingIntent(ir, sc, target)
        }
      }
    }
    // app doesn't exist
    return errorResponseId(
      sc,
      arg0[0].requestUuid,
      arg0[0].from,
      ResolveError.NoAppsFound,
      arg0[0].type,
    )
  }

  oneAppOnly(appIntent: AppIntent): boolean {
    const apps = appIntent.apps.map((a) => a.appId)
    const uniqueApps = apps.filter((v, i, a) => a.indexOf(v) === i).length
    return uniqueApps == 1
  }

  async raiseIntentToAnyApp(
    arg0: IntentRequest[],
    sc: FDC3ServerInstance,
  ): Promise<void> {
    const connectedApps = await sc.getConnectedApps()
    const matchingIntents = arg0.flatMap((i) =>
      sc.getDirectory().retrieveIntents(i.context.type, i.intent, undefined),
    )
    const matchingRegistrations = arg0.flatMap((i) =>
      sc
        .getIntentListeners()
        .filter(
          (r) =>
            r.intentName == i.intent &&
            (r.contextTypes == null ||
              r.contextTypes == undefined ||
              r.contextTypes.includes(i.context.type)),
        ),
    )
    const uniqueIntentNames = [
      ...matchingIntents.map((i) => i.intentName),
      ...matchingRegistrations.map((r) => r.intentName),
    ].filter((v, i, a) => a.indexOf(v) === i)

    const allIntents = sc.getDirectory().retrieveAllIntents()

    const appIntents: AppIntent[] = uniqueIntentNames.map((i) => {
      const directoryAppsWithIntent = matchingIntents
        .filter((mi) => mi.intentName == i)
        .map((mi) => mi.appId)
      const runningDirectoryApps = connectedApps.filter((ca) =>
        directoryAppsWithIntent.includes(ca.appId),
      )
      const appRegistrations = matchingRegistrations
        .filter((registration) => registration.intentName === i) // filter registrations for the current intent
        .map((listener) => ({
          appId: listener.appId,
          instanceId: listener.instanceId,
          state: State.Connected,
        }))
        .filter((appRegistration) =>
          allIntents.every((intent) => intent.appId !== appRegistration.appId),
        ) // filter out apps that have intents registered in the directory

      const runningApps: AppRegistration[] = [
        ...runningDirectoryApps,
        ...appRegistrations,
      ]

      return {
        intent: {
          name: i,
          displayName: i,
        },
        apps: [
          ...runningApps,
          ...directoryAppsWithIntent.map((d) => {
            return { appId: d }
          }),
        ],
      }
    })

    // Intent names can appear from live addIntentListener registrations even when
    // no directory app supports this intent+context (listeners often omit
    // contextTypes). Drop empty AppIntents so we return NoAppsFound instead of
    // sending the client a resolver with nothing to choose.
    const appIntentsWithApps = appIntents.filter((ai) => ai.apps.length > 0)

    const narrowedAppIntents = await this.narrowIntents(
      arg0[0].from,
      appIntentsWithApps,
      arg0[0].context,
      sc,
    )

    if (
      narrowedAppIntents.length == 0 ||
      narrowedAppIntents.every((ai) => ai.apps.length == 0)
    ) {
      // nothing can resolve the intent, fail
      return errorResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        ResolveError.NoAppsFound,
        arg0[0].type,
      )
    }

    if (narrowedAppIntents.length == 1) {
      const theAppIntent = narrowedAppIntents[0]
      if (this.oneAppOnly(theAppIntent)) {
        const instanceCount = theAppIntent.apps.filter(
          (a) => a.instanceId,
        ).length
        const ir: IntentRequest = {
          ...arg0[0],
          intent: narrowedAppIntents[0].intent.name,
        }
        if (instanceCount == 1 && isFullAppIdentifier(theAppIntent.apps[0])) {
          // app is running
          return forwardRequest(ir, theAppIntent.apps[0], sc)
        } else if (instanceCount == 0) {
          return this.startWithPendingIntent(ir, sc, theAppIntent.apps[0])
        }
      }
    }

    if (arg0[0].type == "raiseIntentResponse") {
      // raise intent
      return successResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        {
          appIntent: narrowedAppIntents[0],
        },
        arg0[0].type,
      )
    } else {
      // raise intent for context
      return successResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        { appIntents: narrowedAppIntents },
        arg0[0].type,
      )
    }
  }

  async raiseIntentRequest(
    arg0: RaiseIntentRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const intentRequest: IntentRequest = {
      context: arg0.payload.context,
      from,
      intent: arg0.payload.intent,
      requestUuid: arg0.meta.requestUuid,
      type: "raiseIntentResponse",
    }

    const target = arg0.payload.app
    if (target) {
      if (isFullAppIdentifier(target)) {
        return this.raiseIntentRequestToSpecificInstance(
          [intentRequest],
          sc,
          target,
        )
      } else if (target.appId) {
        return this.raiseIntentRequestToSpecificAppId(
          [intentRequest],
          sc,
          target,
        )
      } else {
        //invalid target
        this.log(
          "Received an invalid target argument for raiseIntent",
          target,
          arg0,
        )
        return errorResponseId(
          sc,
          arg0.meta.requestUuid,
          from,
          ResolveError.TargetAppUnavailable,
          "raiseIntentResponse",
        )
      }
    } else {
      //No target
      return this.raiseIntentToAnyApp([intentRequest], sc)
    }
  }

  async raiseIntentForContextRequest(
    arg0: RaiseIntentForContextRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    // dealing with a specific instance of an app
    const mappedIntents = sc
      .getDirectory()
      .retrieveIntents(arg0.payload.context.type, undefined, undefined)
    const uniqueIntentNames = mappedIntents.filter(
      (v, i, a) => a.findIndex((v2) => v2.intentName == v.intentName) == i,
    )
    const possibleIntentRequests: IntentRequest[] = uniqueIntentNames.map(
      (i) => {
        return {
          context: arg0.payload.context,
          from,
          intent: i.intentName,
          requestUuid: arg0.meta.requestUuid,
          type: "raiseIntentForContextResponse",
        }
      },
    )

    if (possibleIntentRequests.length == 0) {
      return errorResponseId(
        sc,
        arg0.meta.requestUuid,
        from,
        ResolveError.NoAppsFound,
        "raiseIntentForContextResponse",
      )
    }

    const target = arg0.payload.app
    if (target) {
      if (isFullAppIdentifier(target)) {
        return this.raiseIntentRequestToSpecificInstance(
          possibleIntentRequests,
          sc,
          target,
        )
      } else if (target.appId) {
        return this.raiseIntentRequestToSpecificAppId(
          possibleIntentRequests,
          sc,
          target,
        )
      } else {
        //invalid target
        this.log(
          "Received an invalid target argument for raiseIntentForContext",
          target,
          arg0,
        )
        return errorResponseId(
          sc,
          arg0.meta.requestUuid,
          from,
          ResolveError.TargetAppUnavailable,
          "raiseIntentForContextResponse",
        )
      }
    } else {
      //No target
      return this.raiseIntentToAnyApp(possibleIntentRequests, sc)
    }
  }

  async findIntentsByContextRequest(
    r: FindIntentsByContextRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const { context, resultType } = r.payload

    const apps1 = sc
      .getDirectory()
      .retrieveIntents(context?.type, undefined, resultType)

    // fold apps so same intents aren't duplicated
    const apps2: AppIntent[] = []
    //don't use foreach as the handling function is async and needs to process serially
    for (let index = 0; index < apps1.length; index++) {
      const a1 = apps1[index]
      const existing = apps2.find((a2) => a2.intent.name == a1.intentName)
      const runningInstances = await this.retrieveRunningInstances(a1.appId, sc)
      if (existing) {
        existing.apps.push({ appId: a1.appId })
        runningInstances.forEach((ri) =>
          existing.apps.push({ appId: a1.appId, instanceId: ri.instanceId }),
        )
      } else {
        const appIntent: AppIntent = {
          intent: {
            name: a1.intentName,
            displayName: a1.displayName ?? a1.intentName,
          },
          apps: [
            {
              appId: a1.appId,
            },
          ],
        }
        runningInstances.forEach((ri) =>
          appIntent.apps.push({ appId: a1.appId, instanceId: ri.instanceId }),
        )
        apps2.push(appIntent)
      }
    }

    successResponse(
      sc,
      r,
      from,
      {
        appIntents: apps2,
      },
      "findIntentsByContextResponse",
    )
  }

  async findIntentRequest(
    r: FindIntentRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const { intent, context, resultType } = r.payload

    // listeners for connected applications
    const apps2 = (await this.retrieveListeners(intent, sc)).map((lr) => {
      return {
        appId: lr.appId,
        instanceId: lr.instanceId,
      }
    }) as AppIdentifier[]

    // directory entries
    const apps1 = sc
      .getDirectory()
      .retrieveApps(context?.type, intent, resultType)
      .map((a) => {
        return {
          appId: a.appId,
        }
      })

    //combine the lists, no need to de-duplicate as we should return both a directory record with just appId + any instance with appId/instanceId
    const finalApps = [...apps1, ...apps2]

    // just need this for the (deprecated) display name
    const allMatchingIntents = sc
      .getDirectory()
      .retrieveIntents(context?.type, intent, resultType)
    const displayName =
      allMatchingIntents.length > 0
        ? allMatchingIntents[0].displayName
        : undefined

    successResponse(
      sc,
      r,
      from,
      {
        appIntent: {
          intent: {
            name: intent,
            displayName,
          },
          apps: finalApps,
        },
      },
      "findIntentResponse",
    )
  }

  async retrieveListeners(
    intentName: string | undefined,
    sc: FDC3ServerInstance,
  ): Promise<IntentListenerRegistration[]> {
    const activeApps = await sc.getConnectedApps()
    const matching = sc
      .getIntentListeners()
      .filter((r) => r.intentName == intentName)
    const active = matching.filter((r) =>
      activeApps.find((a) => a.instanceId == r.instanceId),
    )
    return active
  }

  async retrieveRunningInstances(appId: string, sc: FDC3ServerInstance) {
    const activeApps = await sc.getConnectedApps()
    const filteredApps = activeApps.filter((a) => a.appId === appId)
    return filteredApps
  }

  async handleEvent(): Promise<void> {}
}

import { LogFunction, MessageHandler } from "../MessageHandler"
import { FDC3ServerInstance } from "../../FDC3ServerInstance"
import { InstanceID, State, ReceivableMessage } from "../../AppRegistration"
import { DirectoryApp } from "../../directory/DirectoryInterface"
import {
  ResolveError,
  AppIdentifier,
  AppMetadata,
  ImplementationMetadata,
} from "@finos/fdc3-standard"
import { BrowserTypes } from "@finos/fdc3-schema"
import { errorResponse, FullAppIdentifier, successResponse } from "./support"
import {
  AgentResponseMessage,
  AppRequestMessage,
  GetInfoRequest,
  isAddContextListenerRequest,
  isFindInstancesRequest,
  isGetAppMetadataRequest,
  isGetInfoRequest,
  isOpenRequest,
  isWebConnectionProtocol4ValidateAppIdentity,
} from "@finos/fdc3-schema/dist/generated/api/BrowserTypes"
import { AppState, PendingApp } from "../../PendingApp"

type BroadcastEvent = BrowserTypes.BroadcastEvent
type AddContextListenerRequest = BrowserTypes.AddContextListenerRequest
type FindInstancesRequest = BrowserTypes.FindInstancesRequest
type GetAppMetadataRequest = BrowserTypes.GetAppMetadataRequest
type OpenRequest = BrowserTypes.OpenRequest
type WebConnectionProtocol4ValidateAppIdentity =
  BrowserTypes.WebConnectionProtocol4ValidateAppIdentity
type WebConnectionProtocol5ValidateAppIdentityFailedResponse =
  BrowserTypes.WebConnectionProtocol5ValidateAppIdentityFailedResponse
type WebConnectionProtocol5ValidateAppIdentitySuccessResponse =
  BrowserTypes.WebConnectionProtocol5ValidateAppIdentitySuccessResponse

export class OpenHandler implements MessageHandler {
  readonly timeoutMs: number
  private readonly log: LogFunction

  constructor(timeoutMs: number, log?: LogFunction) {
    this.timeoutMs = timeoutMs
    this.log = log ?? (() => {})
  }

  shutdown(): void {}

  async accept(
    msg: ReceivableMessage,
    sc: FDC3ServerInstance,
    uuid: InstanceID,
  ): Promise<void> {
    if (isWebConnectionProtocol4ValidateAppIdentity(msg)) {
      return this.handleValidate(
        msg as WebConnectionProtocol4ValidateAppIdentity,
        sc,
        uuid,
      )
    } else if (isAddContextListenerRequest(msg)) {
      //handle context listener adds for pending applications (i.e. opened but awaiting context listener addition to deliver context)
      //  additional handling is performed in BroadcastHandler
      return this.handleAddContextListener(
        msg as AddContextListenerRequest,
        sc,
        uuid,
      )
    } else {
      const from = sc.getInstanceDetails(uuid)
      if (from) {
        try {
          if (isOpenRequest(msg)) {
            return this.open(msg, sc, from)
          } else if (isFindInstancesRequest(msg)) {
            return this.findInstances(msg, sc, from)
          } else if (isGetAppMetadataRequest(msg)) {
            return this.getAppMetadata(msg, sc, from)
          } else if (isGetInfoRequest(msg)) {
            return this.getInfo(msg, sc, from)
          }
        } catch (e) {
          const responseType = (msg.type as string).replace(
            new RegExp("Request$"),
            "Response",
          ) as AgentResponseMessage["type"]
          errorResponse(
            sc,
            msg as unknown as AppRequestMessage,
            from,
            (e as Error).message ?? e,
            responseType,
          )
        }
      } else {
        this.log("Received message from unknown source, ignoring", msg, uuid)
      }
    }
  }

  /**
   * This deals with sending pending context to listeners of newly-opened apps.
   */
  handleAddContextListener(
    arg0: AddContextListenerRequest,
    sc: FDC3ServerInstance,
    from: InstanceID,
  ): void {
    const pendingOpen = sc.getPendingApp(from) as PendingApp | undefined
    if (pendingOpen) {
      const contextType = arg0.payload.contextType
      if (
        pendingOpen.context &&
        pendingOpen.state == AppState.DeliveringContext
      ) {
        if (
          contextType == pendingOpen.context.type ||
          contextType == undefined
        ) {
          // ok, we can deliver to this listener
          const message: BroadcastEvent = {
            meta: {
              eventUuid: sc.createUUID(),
              timestamp: new Date(),
            },
            type: "broadcastEvent",
            payload: {
              channelId: null,
              context: pendingOpen.context,
              originatingApp: {
                appId: pendingOpen.source.appId,
                instanceId: pendingOpen.source.instanceId,
              },
            },
          }

          pendingOpen.setDone()
          sc.removePendingApp(from)
          sc.post(message, from)
        }
      }
    }
  }

  filterPublicDetails(appD: DirectoryApp, appID: AppIdentifier): AppMetadata {
    return {
      appId: appD.appId,
      name: appD.name,
      version: appD.version,
      title: appD.title,
      tooltip: appD.tooltip,
      description: appD.description,
      icons: appD.icons,
      screenshots: appD.screenshots,
      instanceId: appID.instanceId,
    }
  }

  getAppMetadata(
    arg0: GetAppMetadataRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): void {
    const appID = arg0.payload.app
    const details = sc.getDirectory().retrieveAppsById(appID.appId)
    if (details.length > 0) {
      successResponse(
        sc,
        arg0,
        from,
        {
          appMetadata: this.filterPublicDetails(details[0], appID),
        },
        "getAppMetadataResponse",
      )
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        ResolveError.TargetAppUnavailable,
        "getAppMetadataResponse",
      )
    }
  }

  async findInstances(
    arg0: FindInstancesRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const appId = arg0.payload.app.appId
    const openApps = await sc.getConnectedApps()
    const matching = openApps
      .filter((a) => a.appId == appId)
      .map((a) => {
        return {
          appId: a.appId,
          instanceId: a.instanceId,
        }
      })
    successResponse(
      sc,
      arg0,
      from,
      {
        appIdentifiers: matching,
      },
      "findInstancesResponse",
    )
  }

  async open(
    arg0: OpenRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const toOpen = arg0.payload.app
    const context = arg0.payload.context

    try {
      const uuid = await sc.open(toOpen.appId)
      sc.setPendingApp(
        uuid,
        new PendingApp(sc, arg0, context, from, this.timeoutMs),
      )
    } catch (e) {
      errorResponse(sc, arg0, from, (e as Error).message ?? e, "openResponse")
    }
  }

  async getInfo(
    arg0: GetInfoRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const implMetadata: ImplementationMetadata = this.getImplementationMetadata(
      sc,
      {
        appId: from.appId,
        instanceId: from.instanceId,
      },
    )
    successResponse(
      sc,
      arg0,
      from,
      {
        implementationMetadata: implMetadata,
      },
      "getInfoResponse",
    )
  }

  getImplementationMetadata(
    sc: FDC3ServerInstance,
    appIdentity: AppIdentifier,
  ) {
    const appMetadata = this.filterPublicDetails(
      sc.getDirectory().retrieveAppsById(appIdentity.appId)[0],
      appIdentity,
    )
    const details = appIdentity.instanceId
      ? sc.getInstanceDetails(appIdentity.instanceId)
      : undefined
    return {
      provider: sc.provider(),
      providerVersion: sc.providerVersion(),
      fdc3Version: details?.fdc3Version ?? sc.fdc3Version(),
      optionalFeatures: {
        DesktopAgentBridging: false,
        OriginatingAppMetadata: true,
        UserChannelMembershipAPIs: true,
      },
      appMetadata: appMetadata,
    }
  }

  async handleValidate(
    arg0: WebConnectionProtocol4ValidateAppIdentity,
    sc: FDC3ServerInstance,
    from: InstanceID,
  ): Promise<void> {
    const responseMeta = {
      connectionAttemptUuid: arg0.meta.connectionAttemptUuid,
      timestamp: new Date(),
    }

    const returnError = () => {
      const msg: WebConnectionProtocol5ValidateAppIdentityFailedResponse = {
        meta: responseMeta,
        type: "WCP5ValidateAppIdentityFailedResponse",
        payload: {
          message: "App Instance not found",
        },
      }
      sc.post(msg, from)
    }

    const returnSuccess = (appId: string, instanceId: string) => {
      const implMetadata: ImplementationMetadata =
        this.getImplementationMetadata(sc, { appId, instanceId })
      const msg: WebConnectionProtocol5ValidateAppIdentitySuccessResponse = {
        meta: responseMeta,
        type: "WCP5ValidateAppIdentityResponse",
        payload: {
          appId: appId,
          instanceId: instanceId,
          instanceUuid: from,
          implementationMetadata: implMetadata,
        },
      }
      sc.post(msg, instanceId)
    }

    if (arg0.payload.instanceUuid) {
      // existing app reconnecting
      this.log("App attempting to reconnect:", arg0.payload.instanceUuid)
      const appIdentity = sc.getInstanceDetails(arg0.payload.instanceUuid)

      if (appIdentity) {
        // in this case, the app is reconnecting, so let's just re-assign the identity
        this.log(
          `Reassigned existing identity, appId: `,
          appIdentity.appId,
          ", instanceId",
          arg0.payload.instanceUuid,
        )
        sc.setInstanceDetails(from, appIdentity)
        sc.setAppState(from, State.Connected)
        return returnSuccess(appIdentity.appId, appIdentity.instanceId)
      } else {
        //we didn't find the identity, assign a new one
        this.log(
          "Existing identity not found for, assigning a new one: ",
          arg0.payload.instanceUuid,
        )
      }
    }

    // we need to assign an identity to this app - this should have been generated when it was launched
    const appIdentity = sc.getInstanceDetails(from)
    if (appIdentity) {
      sc.setAppState(appIdentity.instanceId, State.Connected)
      returnSuccess(appIdentity.appId, appIdentity.instanceId)

      // make sure, if the opener is listening for this app to open, then it gets informed
      const pendingOpen = sc.getPendingApp(from) as PendingApp | undefined
      if (pendingOpen) {
        if (pendingOpen.state == AppState.Opening) {
          pendingOpen.setOpened(appIdentity)
        }
      }
    } else {
      returnError()
    }
  }

  async handleEvent(): Promise<void> {
    // no-op
  }
}

import { FDC3ServerInstance } from "./FDC3ServerInstance"
import { ContextElement } from "@finos/fdc3-context"
import { AppIdentifier, OpenError } from "@finos/fdc3-standard"
import { BrowserTypes } from "@finos/fdc3-schema"
import { State } from "./AppRegistration"

export enum AppState {
  Opening,
  DeliveringContext,
  Done,
}

type OpenRequest = BrowserTypes.OpenRequest

/** App-provided portion of context metadata (FDC3 3.0). */
export type AppProvidedOpenMetadata = {
  traceId?: string
  signature?: unknown
  antiReplay?: unknown
  custom?: Record<string, unknown>
}

export class PendingApp {
  private readonly sc: FDC3ServerInstance
  private readonly msg: OpenRequest
  readonly context: ContextElement | undefined
  readonly source: AppIdentifier & { instanceId: string }
  readonly appProvidedMetadata: AppProvidedOpenMetadata
  state: AppState = AppState.Opening
  private openedApp: AppIdentifier | undefined = undefined

  constructor(
    sc: FDC3ServerInstance,
    msg: OpenRequest,
    context: ContextElement | undefined,
    source: AppIdentifier & { instanceId: string },
    timeoutMs: number,
    appProvidedMetadata?: AppProvidedOpenMetadata,
  ) {
    this.context = context
    this.source = source
    this.sc = sc
    this.msg = msg
    this.appProvidedMetadata = appProvidedMetadata ?? {}

    setTimeout(() => {
      if (this.state != AppState.Done) {
        this.onError()
      }
    }, timeoutMs)
  }

  private onSuccess() {
    this.sc.setAppState(this.openedApp!.instanceId!, State.Connected)
    this.sc.post(
      {
        type: "openResponse",
        meta: {
          requestUuid: this.msg.meta.requestUuid,
          responseUuid: this.sc.createUUID(),
          timestamp: new Date(),
        },
        payload: {
          appIdentifier: {
            appId: this.openedApp!.appId,
            instanceId: this.openedApp!.instanceId,
          },
        },
      },
      this.source.instanceId,
    )
  }

  private onError() {
    const error =
      this.state == AppState.Opening
        ? OpenError.ApiTimeout
        : OpenError.AppTimeout
    this.state = AppState.Done
    this.sc.post(
      {
        type: "openResponse",
        meta: {
          requestUuid: this.msg.meta.requestUuid,
          responseUuid: this.sc.createUUID(),
          timestamp: new Date(),
        },
        payload: {
          error,
        },
      },
      this.source.instanceId,
    )
  }

  setOpened(openedApp: AppIdentifier) {
    this.openedApp = openedApp
    if (this.context) {
      this.state = AppState.DeliveringContext
    } else {
      this.setDone()
    }
  }

  setDone() {
    this.state = AppState.Done
    this.onSuccess()
  }
}

import { LogFunction, MessageHandler } from "../MessageHandler"
import { InstanceID, State, ReceivableMessage } from "../../AppRegistration"
import {
  HeartbeatEvent,
} from "@finos/fdc3-schema/dist/generated/api/BrowserTypes"
import { FullAppIdentifier } from "./support"
import {
  FDC3ServerInstance,
  HeartbeatActivityEvent,
} from "../../FDC3ServerInstance"
import { FDC3ServerInstanceEvent } from "../../FDC3ServerInstanceEvents"

type HeartbeatDetails = {
  instanceId: string
  time: number
  state: string
}

function convertToText(s?: State): string {
  if (s == undefined) {
    return "Unknown"
  } else {
    switch (s) {
      case State.Pending:
        return "Pending"
      case State.Connected:
        return "Connected"
      case State.NotResponding:
        return "Not Responding"
      case State.Terminated:
        return "Terminated"
    }
  }
}

/*
 * Handles heartbeat pings and responses
 */
export class HeartbeatHandler implements MessageHandler {
  private readonly fdc3Instances: FDC3ServerInstance[] = []
  private readonly lastHeartbeats: Map<InstanceID, number> = new Map()
  private readonly timerFunction: NodeJS.Timeout
  private readonly log: LogFunction

  constructor(
    pingInterval: number = 1000,
    disconnectedAfter: number = 5000,
    deadAfter: number = 20000,
    log?: LogFunction,
  ) {
    this.log = log ?? (() => {})
    this.timerFunction = setInterval(() => {
      this.fdc3Instances.forEach(async (sc) => {
        const apps = await sc.getAllApps()
        apps
          .filter(
            (app) =>
              app.state == State.Connected || app.state == State.NotResponding,
          )
          .forEach((app) => {
            const now = new Date().getTime()
            this.sendHeartbeat(sc, app)

            // check when the last heartbeat happened
            const lastHeartbeat = this.lastHeartbeats.get(app.instanceId)
            const currentState = app.state

            if (lastHeartbeat != undefined) {
              const timeSinceLastHeartbeat = now - lastHeartbeat

              if (
                timeSinceLastHeartbeat < disconnectedAfter &&
                currentState != State.Connected
              ) {
                sc.heartbeatActivity(
                  app.instanceId,
                  HeartbeatActivityEvent.ConnectedResponding,
                )
              } else if (
                timeSinceLastHeartbeat > disconnectedAfter &&
                currentState == State.Connected
              ) {
                sc.heartbeatActivity(
                  app.instanceId,
                  HeartbeatActivityEvent.NotRespondingAfterDisconnectTime,
                )
              } else if (
                timeSinceLastHeartbeat > deadAfter &&
                currentState == State.NotResponding
              ) {
                this.log(
                  `No heartbeat from ${app.instanceId} for ${timeSinceLastHeartbeat}ms. App is considered terminated.`,
                )
                sc.heartbeatActivity(
                  app.instanceId,
                  HeartbeatActivityEvent.NotRespondingAfterDeadTime,
                )
              } else {
                // no action
              }
            } else {
              // start the clock
              this.lastHeartbeats.set(app.instanceId, now)
              sc.heartbeatActivity(
                app.instanceId,
                HeartbeatActivityEvent.ConnectedResponding,
              )
            }
          })
      })
    }, pingInterval)
  }

  heartbeatTimes(): HeartbeatDetails[] {
    const now = new Date().getTime()
    return Array.from(this.lastHeartbeats)
      .map((e) => {
        return {
          instanceId: e[0],
          time: now - e[1],
          state: convertToText(
            this.fdc3Instances
              .map((sc) => sc.getInstanceDetails(e[0]))
              .reduce((a, b) => a || b, undefined)?.state,
          ),
        } as HeartbeatDetails
      })
      .filter((e) => e.state != "Terminated")
  }

  shutdown(): void {
    clearInterval(this.timerFunction)
  }

  async accept(
    msg: ReceivableMessage,
    sc: FDC3ServerInstance,
    from: InstanceID,
  ): Promise<void> {
    if (!this.fdc3Instances.includes(sc)) {
      this.fdc3Instances.push(sc)
    }

    if (msg.type == "heartbeatAcknowledgementRequest") {
      const app = sc.getInstanceDetails(from)
      if (app) {
        this.lastHeartbeats.set(app.instanceId, new Date().getTime())
      }
    }

    if (msg.type == "WCP6Goodbye") {
      const app = sc.getInstanceDetails(from)
      if (app) {
        sc.setAppState(from, State.Terminated)
      }
    }
  }

  async sendHeartbeat(
    sc: FDC3ServerInstance,
    app: FullAppIdentifier,
  ): Promise<void> {
    const event: HeartbeatEvent = {
      type: "heartbeatEvent",
      meta: {
        timestamp: new Date(),
        eventUuid: sc.createUUID(),
      },
      payload: {},
    }
    sc.post(event, app.instanceId)
  }

  async handleEvent(
    e: FDC3ServerInstanceEvent,
    i: FDC3ServerInstance,
  ): Promise<void> {
    if (e.type === "shutdown") {
      if (this.fdc3Instances.includes(i)) {
        this.fdc3Instances.splice(this.fdc3Instances.indexOf(i), 1)
      }
    }
  }
}

import { LogFunction, MessageHandler } from "../MessageHandler"
import {
  ChannelState,
  ChannelType,
  ContextListenerRegistration,
  DesktopAgentEventListener,
  PrivateChannelEventListener,
  FDC3ServerInstance,
  StoredContextMetadata,
} from "../../FDC3ServerInstance"
import {
  InstanceID,
  ReceivableMessage,
  Fdc3ApiVersion,
} from "../../AppRegistration"
import {
  AppIdentifier,
  ChannelError,
  PrivateChannelEventTypes,
} from "@finos/fdc3-standard"
import { successResponse, errorResponse, FullAppIdentifier } from "./support"
import {
  AddContextListenerRequest,
  AddEventListenerRequest,
  AgentResponseMessage,
  AppRequestMessage,
  BroadcastRequest,
  ChannelChangedEvent,
  ClearContextRequest,
  ContextClearedEvent,
  ContextListenerUnsubscribeRequest,
  CreatePrivateChannelRequest,
  EventListenerUnsubscribeRequest,
  GetCurrentChannelRequest,
  GetCurrentContextRequest,
  GetOrCreateChannelRequest,
  GetUserChannelsRequest,
  JoinUserChannelRequest,
  LeaveCurrentChannelRequest,
  PrivateChannelAddEventListenerRequest,
  PrivateChannelDisconnectRequest,
  PrivateChannelOnAddContextListenerEvent,
  PrivateChannelOnDisconnectEvent,
  PrivateChannelOnUnsubscribeEvent,
  PrivateChannelUnsubscribeEventListenerRequest,
} from "@finos/fdc3-schema-v3/dist/generated/api/BrowserTypes"
import {
  PrivateChannelDisconnectServerInstanceEvent,
  FDC3ServerInstanceEvent,
  ChannelChangedServerInstanceEvent,
} from "../../FDC3ServerInstanceEvents"

type PrivateChannelEvents =
  | PrivateChannelOnAddContextListenerEvent
  | PrivateChannelOnUnsubscribeEvent
  | PrivateChannelOnDisconnectEvent

function onlyUniqueAppIds(
  value: AppIdentifier,
  index: number,
  self: AppIdentifier[],
) {
  const fi = self.findIndex((v) => v.instanceId === value.instanceId)
  return fi === index
}

/** Matches a listener's contextType (null = all, string, or string[]) against a context type. */
function matchesContextType(
  listenerType: string | string[] | null,
  contextType: string,
): boolean {
  if (listenerType == null) {
    return true
  }
  if (Array.isArray(listenerType)) {
    return listenerType.includes(contextType)
  }
  return listenerType == contextType
}

export class BroadcastHandler implements MessageHandler {
  private readonly log: LogFunction
  private readonly apiVersion: Fdc3ApiVersion = "3.0"

  constructor(log?: LogFunction) {
    this.log = log ?? (() => {})
  }

  shutdown(): void {}

  private matchesApiVersion(sc: FDC3ServerInstance, instanceId: string): boolean {
    const version = sc.getInstanceDetails(instanceId)?.fdc3Version ?? "2.2"
    return version === this.apiVersion
  }

  getCurrentChannel(
    from: FullAppIdentifier,
    sc: FDC3ServerInstance,
  ): ChannelState | null {
    return sc.getCurrentChannel(from.instanceId)
  }

  fireChannelChangedEvent(
    channelId: string | null,
    sc: FDC3ServerInstance,
    instanceId: string,
  ) {
    const hasChannelChangedListener = sc
      .getDesktopAgentEventListeners()
      .some(
        (listener) =>
          listener.instanceId === instanceId &&
          (listener.eventType === null ||
            listener.eventType === "USER_CHANNEL_CHANGED"),
      )
    if (!hasChannelChangedListener) {
      return
    }

    const event: ChannelChangedEvent = {
      meta: {
        eventUuid: sc.createUUID(),
        timestamp: new Date(),
      },
      type: "channelChangedEvent",
      payload: {
        newChannelId: channelId,
      },
    }

    sc.post(event, instanceId)
  }

  /**
   * Notifies apps that have registered a matching `CONTEXT_CLEARED` listener that context has
   * been cleared on a channel. Routing follows the scope carried on each registration:
   *  - Channel-scoped listeners (`channelId` set) match the cleared channel exactly.
   *  - Desktop Agent-level listeners (`channelId` null) match when the cleared channel is the
   *    listening app's current User channel.
   */
  fireContextClearedEvent(
    channelId: string,
    contextType: string | null,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const matchingInstanceIds = sc
      .getDesktopAgentEventListeners()
      .filter(
        (listener) =>
          listener.eventType === null || listener.eventType === "CONTEXT_CLEARED",
      )
      .filter((listener) => {
        if (listener.channelId !== null) {
          return listener.channelId === channelId
        }
        const currentChannel = sc.getCurrentChannel(listener.instanceId)
        return currentChannel != null && currentChannel.id === channelId
      })
      .filter((listener) => listener.instanceId !== from.instanceId)
      .map((listener) => listener.instanceId)
      .filter((instanceId, index, self) => self.indexOf(instanceId) === index)

    if (matchingInstanceIds.length === 0) {
      return
    }

    const event: ContextClearedEvent = {
      meta: {
        eventUuid: sc.createUUID(),
        timestamp: new Date(),
      },
      type: "contextClearedEvent",
      payload: {
        channelId,
        contextType,
      },
    }

    matchingInstanceIds.forEach((instanceId) => sc.post(event, instanceId))
  }

  convertChannelTypeToString(type: ChannelType): string {
    switch (type) {
      case ChannelType.app:
        return "app"
      case ChannelType.user:
        return "user"
      case ChannelType.private:
        return "private"
    }
  }

  async accept(
    msg: ReceivableMessage,
    sc: FDC3ServerInstance,
    uuid: InstanceID,
  ) {
    const from = sc.getInstanceDetails(uuid)

    if (from == null) {
      // this handler only deals with connected apps
      return
    }

    this.log(`BroadcastHandler: accept called with msg: ${JSON.stringify(msg)}`)

    try {
      switch (msg.type as string | null) {
        case "getOrCreateChannelRequest":
          return this.handleGetOrCreateRequest(
            msg as unknown as GetOrCreateChannelRequest,
            sc,
            from,
          )

        case "getUserChannelsRequest":
          return this.handleGetUserChannelsRequest(
            msg as unknown as GetUserChannelsRequest,
            sc,
            from,
          )
        case "leaveCurrentChannelRequest":
          return this.handleLeaveCurrentChannelRequest(
            msg as unknown as LeaveCurrentChannelRequest,
            sc,
            from,
          )
        case "joinUserChannelRequest":
          return this.handleJoinUserChannelRequest(
            msg as unknown as JoinUserChannelRequest,
            sc,
            from,
          )
        case "getCurrentChannelRequest":
          return this.handleGetCurrentChannelRequest(
            msg as unknown as GetCurrentChannelRequest,
            sc,
            from,
          )

        case "broadcastRequest":
          return this.handleBroadcastRequest(
            msg as unknown as BroadcastRequest, sc, from)
        case "clearContextRequest":
          return this.handleClearContextRequest(
            msg as unknown as ClearContextRequest,
            sc,
            from,
          )

        case "addContextListenerRequest":
          return this.handleAddContextListenerRequest(
            msg as unknown as AddContextListenerRequest,
            sc,
            from,
          )
        case "contextListenerUnsubscribeRequest":
          return this.handleContextListenerUnsubscribeRequest(
            msg as unknown as ContextListenerUnsubscribeRequest,
            sc,
            from,
          )

        case "createPrivateChannelRequest":
          return this.handleCreatePrivateChannelRequest(
            msg as unknown as CreatePrivateChannelRequest,
            sc,
            from,
          )
        case "privateChannelDisconnectRequest":
          return this.handlePrivateChannelDisconnectRequest(
            msg as unknown as PrivateChannelDisconnectRequest,
            sc,
            from,
          )

        case "privateChannelAddEventListenerRequest":
          return this.handlePrivateChannelAddEventListenerRequest(
            msg as unknown as PrivateChannelAddEventListenerRequest,
            from,
            sc,
          )
        case "privateChannelUnsubscribeEventListenerRequest":
          return this.handlePrivateChannelUnsubscribeEventListenerRequest(
            msg as unknown as PrivateChannelUnsubscribeEventListenerRequest,
            sc,
            from,
          )

        case "getCurrentContextRequest":
          return this.handleGetCurrentContextRequest(
            msg as unknown as GetCurrentContextRequest,
            sc,
            from,
          )

        case "addEventListenerRequest":
          return this.handleAddEventListenerRequest(
            msg as unknown as AddEventListenerRequest,
            sc,
            from,
          )
        case "eventListenerUnsubscribeRequest":
          return this.handleEventListenerUnsubscribeRequest(
            msg as unknown as EventListenerUnsubscribeRequest,
            sc,
            from,
          )
      }
    } catch (e) {
      const responseType = (msg.type as string).replace(
        new RegExp("Request$"),
        "Response",
      )
      errorResponse(
        sc,
        msg as unknown as AppRequestMessage,
        from,
        (e as Error).message ?? e,
        responseType as AgentResponseMessage["type"],
      )
    }
  }

  handleAddEventListenerRequest(
    arg0: AddEventListenerRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const payload = arg0.payload as { type?: string | null; channelId?: string | null }
    const channelId = payload.channelId ?? null
    if (channelId !== null && sc.getChannelById(channelId) === null) {
      errorResponse(
        sc,
        arg0,
        from,
        ChannelError.NoChannelFound,
        "addEventListenerResponse",
      )
      return
    }

    const lr: DesktopAgentEventListener = {
      appId: from.appId,
      instanceId: from.instanceId ?? "no-instance-id",
      listenerUuid: sc.createUUID(),
      eventType: payload.type ?? null,
      channelId: channelId,
    }

    sc.addDesktopAgentEventListener(lr)
    successResponse(
      sc,
      arg0,
      from,
      { listenerUUID: lr.listenerUuid },
      "addEventListenerResponse",
    )
  }

  handleEventListenerUnsubscribeRequest(
    arg0: EventListenerUnsubscribeRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const removed = sc.removeDesktopAgentEventListener(
      arg0.payload.listenerUUID,
    )
    if (removed) {
      successResponse(sc, arg0, from, {}, "eventListenerUnsubscribeResponse")
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        "ListenerNotFound",
        "eventListenerUnsubscribeResponse",
      )
    }
  }

  handleCreatePrivateChannelRequest(
    arg0: CreatePrivateChannelRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const id = sc.createUUID()
    sc.addChannelState({
      id,
      type: ChannelType.private,
      context: [],
      displayMetadata: {},
    })

    successResponse(
      sc,
      arg0,
      from,
      {
        privateChannel: {
          id,
          type: this.convertChannelTypeToString(ChannelType.private),
        },
      },
      "createPrivateChannelResponse",
    )
  }

  handleGetCurrentContextRequest(
    arg0: GetCurrentContextRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const channel = sc.getChannelById(arg0.payload.channelId)
    const type = arg0.payload.contextType

    if (channel) {
      const stored = type
        ? (channel.context.find((c) => c.context.type == type) ?? null)
        : (channel.context[0] ?? null)
      successResponse(
        sc,
        arg0,
        from,
        {
          context: stored?.context ?? null,
          metadata: stored?.metadata ?? null,
        },
        "getCurrentContextResponse",
      )
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        ChannelError.NoChannelFound,
        "getCurrentContextResponse",
      )
    }
  }

  handlePrivateChannelUnsubscribeEventListenerRequest(
    arg0: PrivateChannelUnsubscribeEventListenerRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const removed = sc.removePrivateChannelEventListener(
      arg0.payload.listenerUUID,
    )
    if (removed) {
      successResponse(
        sc,
        arg0,
        from,
        {},
        "privateChannelUnsubscribeEventListenerResponse",
      )
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        "ListenerNotFound",
        "privateChannelUnsubscribeEventListenerResponse",
      )
    }
  }

  handlePrivateChannelDisconnectRequest(
    arg0: PrivateChannelDisconnectRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const toUnsubscribe = sc
      .getContextListeners()
      .filter((r) => r.appId == from.appId && r.instanceId == from.instanceId)
      .filter((r) => r.channelId == arg0.payload.channelId)

    toUnsubscribe.forEach((u) => {
      this.invokePrivateChannelEventListeners(
        arg0.payload.channelId,
        "unsubscribe",
        "privateChannelOnUnsubscribeEvent",
        sc,
        u.contextType,
      )
    })

    toUnsubscribe.forEach((u) => {
      sc.removeContextListener(u.listenerUuid, u.instanceId)
    })

    this.invokePrivateChannelEventListeners(
      arg0.payload.channelId,
      "disconnect",
      "privateChannelOnDisconnectEvent",
      sc,
    )
    successResponse(sc, arg0, from, {}, "privateChannelDisconnectResponse")
  }

  handleContextListenerUnsubscribeRequest(
    arg0: ContextListenerUnsubscribeRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const rl = sc
      .getContextListeners()
      .find(
        (r) =>
          r.listenerUuid == arg0.payload.listenerUUID &&
          r.instanceId == from.instanceId,
      )

    if (rl) {
      const channel = sc.getChannelById(rl.channelId)
      this.invokePrivateChannelEventListeners(
        channel?.id ?? null,
        "unsubscribe",
        "privateChannelOnUnsubscribeEvent",
        sc,
        rl.contextType,
      )
      sc.removeContextListener(arg0.payload.listenerUUID, from.instanceId)
      successResponse(sc, arg0, from, {}, "contextListenerUnsubscribeResponse")
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        "ListenerNotFound",
        "contextListenerUnsubscribeResponse",
      )
    }
  }

  handleAddContextListenerRequest(
    arg0: AddContextListenerRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    let channelId = null

    if (arg0.payload?.channelId) {
      const channel = sc.getChannelById(arg0.payload?.channelId)

      if (channel == null) {
        errorResponse(
          sc,
          arg0,
          from,
          ChannelError.NoChannelFound,
          "addContextListenerResponse",
        )
        return
      } else {
        channelId = channel.id
      }
    }

    // Support both singular contextType and plural contextTypes (xor / normalize)
    const lr: ContextListenerRegistration = {
      appId: from.appId,
      instanceId: from.instanceId ?? "no-instance-id",
      channelId: channelId,
      listenerUuid: sc.createUUID(),
      contextType: arg0.payload.contextTypes ?? arg0.payload.contextType ?? null,
    }

    sc.addContextListener(lr)
    this.invokePrivateChannelEventListeners(
      channelId,
      "addContextListener",
      "privateChannelOnAddContextListenerEvent",
      sc,
      lr.contextType,
    )
    successResponse(
      sc,
      arg0,
      from,
      { listenerUUID: lr.listenerUuid },
      "addContextListenerResponse",
    )
  }

  handleBroadcastRequest(
    arg0: BroadcastRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const matchesExactChannel = (r: ContextListenerRegistration) => {
      return r.channelId == arg0.payload.channelId
    }

    const matchesUserChannel = (r: ContextListenerRegistration) => {
      const uc = sc.getCurrentChannel(r.instanceId)
      const ucId = uc ? uc.id : null
      return r.channelId == null && ucId == arg0.payload.channelId
    }

    const matchingListeners = sc
      .getContextListeners()
      .filter((r) => matchesExactChannel(r) || matchesUserChannel(r))
      .filter((r) =>
        matchesContextType(r.contextType, arg0.payload.context.type),
      )
      .filter((r) => r.instanceId !== from.instanceId)

    const matchingApps: FullAppIdentifier[] = matchingListeners
      .map((r) => {
        return { appId: r.appId, instanceId: r.instanceId }
      })
      .filter(onlyUniqueAppIds)

    const appProvidedMetadata = arg0.payload.metadata ?? {}

    const metadata: StoredContextMetadata = {
      source: { appId: from.appId, instanceId: from.instanceId },
      timestamp: new Date(),
      traceId: appProvidedMetadata.traceId ?? sc.createUUID(),
      ...(appProvidedMetadata.signature !== undefined && {
        signature: appProvidedMetadata.signature,
      }),
      ...(appProvidedMetadata.antiReplay !== undefined && {
        antiReplay: appProvidedMetadata.antiReplay,
      }),
      ...(appProvidedMetadata.custom !== undefined && {
        custom: appProvidedMetadata.custom,
      }),
    }

    const msg = {
      meta: {
        eventUuid: sc.createUUID(),
        timestamp: new Date(),
      },
      type: "broadcastEvent" as const,
      payload: {
        channelId: arg0.payload.channelId,
        context: arg0.payload.context,
        metadata,
      },
    }

    matchingApps.forEach((app) => {
      sc.post(msg, app.instanceId)
    })

    sc.updateChannelContext(arg0.payload.channelId, arg0.payload.context, metadata)
    successResponse(sc, arg0, from, {}, "broadcastResponse")
  }

  handleClearContextRequest(
    arg0: ClearContextRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const channelId = arg0.payload.channelId
    const contextType = arg0.payload.contextType ?? null

    const channel = sc.getChannelById(channelId)
    if (!channel) {
      errorResponse(
        sc,
        arg0,
        from,
        ChannelError.NoChannelFound,
        "clearContextResponse",
      )
      return
    }

    sc.clearChannelContext(channelId, contextType)
    this.fireContextClearedEvent(channelId, contextType, sc, from)
    successResponse(sc, arg0, from, {}, "clearContextResponse")
  }

  handleGetCurrentChannelRequest(
    arg0: GetCurrentChannelRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const currentChannel = this.getCurrentChannel(from, sc)
    if (currentChannel) {
      successResponse(
        sc,
        arg0,
        from,
        {
          channel: {
            id: currentChannel.id,
            type: this.convertChannelTypeToString(currentChannel.type),
            displayMetadata: currentChannel.displayMetadata,
          },
        },
        "getCurrentChannelResponse",
      )
    } else {
      successResponse(
        sc,
        arg0,
        from,
        { channel: null },
        "getCurrentChannelResponse",
      )
    }
  }

  handleJoinUserChannelRequest(
    arg0: JoinUserChannelRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const newChannel = sc.getChannelById(arg0.payload.channelId)
    if (newChannel == null || newChannel.type != ChannelType.user) {
      return errorResponse(
        sc,
        arg0,
        from,
        ChannelError.NoChannelFound,
        "joinUserChannelResponse",
      )
    }

    const instanceId = from.instanceId ?? "no-instance-id"
    sc.setCurrentChannel(instanceId, newChannel)
    successResponse(sc, arg0, from, {}, "joinUserChannelResponse")
  }

  handleLeaveCurrentChannelRequest(
    arg0: LeaveCurrentChannelRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const instanceId = from.instanceId ?? "no-instance-id"
    sc.setCurrentChannel(instanceId, null)
    successResponse(sc, arg0, from, {}, "leaveCurrentChannelResponse")
  }

  handleGetOrCreateRequest(
    arg0: GetOrCreateChannelRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const id = arg0.payload.channelId
    let channel = sc.getChannelById(id)

    if (!channel) {
      channel = {
        id: id,
        type: ChannelType.app,
        context: [],
        displayMetadata: {},
      }
      sc.addChannelState(channel)
    }

    // only allow retrieval of app channels or user channels
    if (channel.type == ChannelType.app || channel.type == ChannelType.user) {
      successResponse(
        sc,
        arg0,
        from,
        {
          channel: {
            id: channel.id,
            type: this.convertChannelTypeToString(channel.type),
          },
        },
        "getOrCreateChannelResponse",
      )
    } else {
      // block retrieval of private channels
      errorResponse(
        sc,
        arg0,
        from,
        ChannelError.AccessDenied,
        "getOrCreateChannelResponse",
      )
    }
  }

  handleGetUserChannelsRequest(
    arg0: GetUserChannelsRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ) {
    const userChannels = sc
      .getChannelStates()
      .filter((c) => c.type == ChannelType.user)
    successResponse(
      sc,
      arg0,
      from,
      {
        userChannels: userChannels.map((c) => ({
          id: c.id,
          type: this.convertChannelTypeToString(c.type),
          displayMetadata: c.displayMetadata,
        })),
      },
      "getUserChannelsResponse",
    )
  }

  handlePrivateChannelAddEventListenerRequest(
    arg0: PrivateChannelAddEventListenerRequest,
    from: FullAppIdentifier,
    sc: FDC3ServerInstance,
  ) {
    const channel = sc.getChannelById(arg0.payload.privateChannelId)

    if (channel == null || channel.type != ChannelType.private) {
      errorResponse(
        sc,
        arg0,
        from,
        ChannelError.NoChannelFound,
        "privateChannelAddEventListenerResponse",
      )
    } else {
      const el = {
        appId: from.appId,
        instanceId: from.instanceId,
        channelId: arg0.payload.privateChannelId,
        eventType: arg0.payload.listenerType,
        listenerUuid: sc.createUUID(),
      } as PrivateChannelEventListener
      sc.addPrivateChannelEventListener(el)
      successResponse(
        sc,
        arg0,
        from,
        { listenerUUID: el.listenerUuid },
        "privateChannelAddEventListenerResponse",
      )
    }
  }

  invokePrivateChannelEventListeners(
    privateChannelId: string | null,
    eventType: PrivateChannelEventTypes,
    messageType:
      | "privateChannelOnAddContextListenerEvent"
      | "privateChannelOnUnsubscribeEvent"
      | "privateChannelOnDisconnectEvent",
    sc: FDC3ServerInstance,
    contextType?: string | string[] | null,
  ) {
    if (privateChannelId) {
      const payload: {
        privateChannelId: string
        contextType?: string | null
        contextTypes?: string[]
      } = {
        privateChannelId,
      }
      if (Array.isArray(contextType)) {
        payload.contextTypes = contextType
      } else {
        payload.contextType = contextType
      }

      const msg: PrivateChannelEvents = {
        type: messageType,
        meta: {
          eventUuid: sc.createUUID(),
          timestamp: new Date(),
        },
        payload,
      } as PrivateChannelEvents

      this.log("invokePrivateChannelEventListeners msg: ", msg)
      sc.getPrivateChannelEventListeners()
        .filter(
          (listener) =>
            listener.channelId == privateChannelId &&
            (listener.eventType == eventType || listener.eventType == null),
        )
        .filter((listener) => this.matchesApiVersion(sc, listener.instanceId))
        .filter(onlyUniqueAppIds)
        .forEach((e) => {
          this.log(
            `invokePrivateChannelEventListeners: posting to instance ${e.instanceId}`,
          )
          sc.post(msg, e.instanceId)
        })
    }
  }

  async handleEvent(
    e: FDC3ServerInstanceEvent,
    sc: FDC3ServerInstance,
  ): Promise<void> {
    if (e.type === "privateChannelDisconnect") {
      const event = e as PrivateChannelDisconnectServerInstanceEvent

      const privateChannelsToDisconnect = new Set<string>()

      sc.getContextListeners()
        .filter((l) => l.channelId == event.channelId)
        .filter((l) => this.matchesApiVersion(sc, l.instanceId))
        .forEach((l) => {
          this.invokePrivateChannelEventListeners(
            l.channelId,
            "unsubscribe",
            "privateChannelOnUnsubscribeEvent",
            sc,
            l.contextType,
          )
          if (l.channelId) {
            privateChannelsToDisconnect.add(l.channelId)
          }
        })

      privateChannelsToDisconnect.forEach((chan) => {
        this.invokePrivateChannelEventListeners(
          chan,
          "disconnect",
          "privateChannelOnDisconnectEvent",
          sc,
        )
      })
    } else if (e.type === "channelChanged") {
      const event = e as ChannelChangedServerInstanceEvent
      if (!this.matchesApiVersion(sc, event.instanceId)) {
        return
      }
      return this.fireChannelChangedEvent(event.channelId, sc, event.instanceId)
    }
  }
}

import {
  AgentResponseMessage,
  AppRequestMessage,
} from "@finos/fdc3-schema-v3/dist/generated/api/BrowserTypes"
import { AppIdentifier } from "@finos/fdc3-standard"
import { FDC3ServerInstance } from "../../FDC3ServerInstance"

/** Interface representing a full specified app identifier (instanceId is optional in the API type). */
export interface FullAppIdentifier {
  readonly appId: string
  readonly instanceId: string
}

export function isFullAppIdentifier(
  identifier: AppIdentifier | FullAppIdentifier,
): identifier is FullAppIdentifier {
  const typedIdentifier = identifier as FullAppIdentifier
  return (
    typedIdentifier.instanceId !== undefined &&
    typedIdentifier.appId !== undefined
  )
}

export function successResponse(
  sc: FDC3ServerInstance,
  request: AppRequestMessage,
  to: FullAppIdentifier,
  payload: AgentResponseMessage["payload"],
  type: AgentResponseMessage["type"],
) {
  return successResponseId(sc, request.meta.requestUuid, to, payload, type)
}

export function errorResponse(
  sc: FDC3ServerInstance,
  request: AppRequestMessage,
  to: FullAppIdentifier,
  error: string,
  type: AgentResponseMessage["type"],
) {
  return errorResponseId(sc, request.meta.requestUuid, to, error, type)
}

export function successResponseId(
  sc: FDC3ServerInstance,
  requestId: string,
  to: FullAppIdentifier,
  payload: AgentResponseMessage["payload"],
  type: AgentResponseMessage["type"],
) {
  const msg = {
    meta: {
      responseUuid: sc.createUUID(),
      requestUuid: requestId,
      timestamp: new Date(),
    },
    type,
    payload,
  }
  sc.post(msg, to.instanceId!)
}

export function errorResponseId(
  sc: FDC3ServerInstance,
  requestId: string,
  to: FullAppIdentifier,
  error: string,
  type: AgentResponseMessage["type"],
) {
  sc.post(
    {
      meta: {
        responseUuid: sc.createUUID(),
        requestUuid: requestId,
        timestamp: new Date(),
      },
      type,
      payload: {
        error,
      },
    } as AgentResponseMessage,
    to.instanceId!,
  )
}

import { LogFunction, MessageHandler } from "../MessageHandler"
import {
  FDC3ServerInstance,
  IntentListenerRegistration,
} from "../../FDC3ServerInstance"
import { AppRegistration, InstanceID, State, ReceivableMessage } from "../../AppRegistration"
import { DirectoryIntent } from "../../directory/DirectoryInterface"
import { Context } from "@finos/fdc3-context-v3"
import { AppIntent, AppIdentifier } from "@finos/fdc3-standard"
import {
  AppProvidableContextMetadata,
  ResolveError,
} from "@finos/fdc3-standard-v3"
import {
  errorResponse,
  errorResponseId,
  FullAppIdentifier,
  isFullAppIdentifier,
  successResponse,
  successResponseId,
} from "./support"
import {
  FindIntentsByContextRequest,
  FindIntentRequest,
  AddIntentListenerRequest,
  IntentListenerUnsubscribeRequest,
  RaiseIntentRequest,
  RaiseIntentForContextRequest,
  IntentResultRequest,
  AppRequestMessage,
  AgentResponseMessage,
} from "@finos/fdc3-schema-v3/dist/generated/api/BrowserTypes"

type IntentRequest = {
  intent: string
  context: Context
  requestUuid: string
  from: FullAppIdentifier
  type: "raiseIntentResponse" | "raiseIntentForContextResponse"
  appProvidedMetadata?: AppProvidableContextMetadata
  /**
   * Caller's preference for how an instance of the target application is selected:
   * - `true`: a new instance MUST be launched even if existing instances are available;
   * - `false`: an existing instance MUST be used and a new instance MUST NOT be launched;
   * - `undefined`: the Desktop Agent applies its default resolution behavior.
   */
  newInstance?: boolean
}

/**
 * Re-writes the request to forward it on to the target application
 */
async function forwardRequest(
  arg0: IntentRequest,
  to: FullAppIdentifier,
  sc: FDC3ServerInstance,
): Promise<void> {
  const appProvidedMeta = arg0.appProvidedMetadata ?? {}
  const out = {
    type: "intentEvent" as const,
    payload: {
      context: arg0.context,
      intent: arg0.intent,
      metadata: {
        source: {
          appId: arg0.from.appId,
          instanceId: arg0.from.instanceId,
        },
        timestamp: new Date(),
        traceId: appProvidedMeta.traceId ?? sc.createUUID(),
        ...(appProvidedMeta.signature !== undefined && {
          signature: appProvidedMeta.signature,
        }),
        ...(appProvidedMeta.antiReplay !== undefined && {
          antiReplay: appProvidedMeta.antiReplay,
        }),
        ...(appProvidedMeta.custom !== undefined && {
          custom: appProvidedMeta.custom,
        }),
      },
      raiseIntentRequestUuid: arg0.requestUuid,
    },
    meta: {
      eventUuid: sc.createUUID(),
      timestamp: new Date(),
    },
  }

  // register the resolution destination
  sc.addPendingResolution(arg0.requestUuid, arg0.from)
  await sc.post(out, to.instanceId)
  successResponseId(
    sc,
    arg0.requestUuid,
    arg0.from,
    {
      intentResolution: {
        intent: arg0.intent,
        source: { appId: to.appId, instanceId: to.instanceId },
      },
    },
    arg0.type,
  )
}

/**
 * A pending intent is one for an app that hasn't registered it's intent listener yet.
 * (Possibly it is being opened)
 *
 * Pending intents wait for that registration and then message the app.
 */
class PendingIntent {
  complete: boolean = false
  r: IntentRequest
  appId: AppIdentifier
  sc: FDC3ServerInstance
  ih: IntentHandler

  constructor(
    r: IntentRequest,
    sc: FDC3ServerInstance,
    ih: IntentHandler,
    appId: AppIdentifier,
  ) {
    this.r = r
    this.appId = appId
    this.sc = sc
    this.ih = ih

    // handle the timeout
    setTimeout(() => {
      if (!this.complete) {
        errorResponseId(
          sc,
          r.requestUuid,
          r.from,
          ResolveError.IntentDeliveryFailed,
          r.type,
        )
        this.ih.pendingIntents.delete(this)
      }
    }, ih.timeoutMs)
  }

  async accept(arg0: IntentListenerRegistration): Promise<void> {
    if (
      arg0.appId == this.appId.appId &&
      arg0.intentName == this.r.intent &&
      (arg0.contextTypes == null ||
        arg0.contextTypes == undefined ||
        arg0.contextTypes.includes(this.r.context.type)) &&
      (arg0.instanceId == this.appId.instanceId ||
        this.appId.instanceId == undefined)
    ) {
      this.complete = true
      this.ih.pendingIntents.delete(this)
      forwardRequest(
        this.r,
        { appId: arg0.appId, instanceId: arg0.instanceId },
        this.sc,
      )
    }
  }
}

export class IntentHandler implements MessageHandler {
  readonly pendingIntents: Set<PendingIntent> = new Set()
  readonly timeoutMs: number
  private readonly log: LogFunction

  constructor(timeoutMs: number, log?: LogFunction) {
    this.timeoutMs = timeoutMs
    this.log = log ?? (() => {})
  }

  shutdown(): void {}

  async narrowIntents(
    raiser: AppIdentifier,
    appIntents: AppIntent[],
    context: Context,
    sc: FDC3ServerInstance,
  ): Promise<AppIntent[]> {
    const out = await sc.narrowIntents(raiser, appIntents, context)
    return out
  }

  async accept(
    msg: ReceivableMessage,
    sc: FDC3ServerInstance,
    uuid: InstanceID,
  ): Promise<void> {
    const from = sc.getInstanceDetails(uuid)

    if (from == null) {
      // this handler only deals with connected apps
      return
    }

    try {
      switch (msg.type as string) {
        case "findIntentsByContextRequest":
          return await this.findIntentsByContextRequest(
            msg as unknown as FindIntentsByContextRequest,
            sc,
            from,
          )
        case "findIntentRequest":
          return await this.findIntentRequest(
            msg as unknown as FindIntentRequest,
            sc,
            from,
          )

        case "addIntentListenerRequest":
          return await this.onAddIntentListener(
            msg as unknown as AddIntentListenerRequest,
            sc,
            from,
          )
        case "intentListenerUnsubscribeRequest":
          return await this.onUnsubscribe(
            msg as unknown as IntentListenerUnsubscribeRequest,
            sc,
            from,
          )

        case "raiseIntentRequest":
          return await this.raiseIntentRequest(
            msg as unknown as RaiseIntentRequest,
            sc,
            from,
          )
        case "raiseIntentForContextRequest":
          return await this.raiseIntentForContextRequest(
            msg as unknown as RaiseIntentForContextRequest,
            sc,
            from,
          )
        case "intentResultRequest":
          return await this.intentResultRequest(
            msg as unknown as IntentResultRequest,
            sc,
            from,
          )
      }
    } catch (e) {
      const responseType = (msg.type as string).replace(
        new RegExp("Request$"),
        "Response",
      ) as AgentResponseMessage["type"]
      errorResponse(
        sc,
        msg as unknown as AppRequestMessage,
        from,
        (e as Error).message ?? e,
        responseType,
      )
    }
  }

  /**
   * Called when target app handles an intent
   */
  intentResultRequest(
    arg0: IntentResultRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): void | PromiseLike<void> {
    const requestId = arg0.payload.raiseIntentRequestUuid
    const to = sc.getPendingResolution(requestId)
    if (to && to.instanceId) {
      const appMeta = arg0.payload.metadata ?? {}
      const resultMetadata = {
        source: { appId: from.appId, instanceId: from.instanceId },
        timestamp: new Date(),
        traceId: appMeta.traceId ?? sc.createUUID(),
        ...(appMeta.signature !== undefined && { signature: appMeta.signature }),
        ...(appMeta.antiReplay !== undefined && {
          antiReplay: appMeta.antiReplay,
        }),
        ...(appMeta.custom !== undefined && { custom: appMeta.custom }),
      }

      successResponseId(
        sc,
        requestId,
        to as FullAppIdentifier,
        {
          intentResult: arg0.payload.intentResult,
          resultMetadata,
        },
        "raiseIntentResultResponse",
      )

      sc.removePendingResolution(requestId)
    }
    // respond to the app that handled the intent
    successResponse(sc, arg0, from, {}, "intentResultResponse")
  }

  onUnsubscribe(
    arg0: IntentListenerUnsubscribeRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): void {
    const id = arg0.payload.listenerUUID
    const removed = sc.removeIntentListener(id)
    if (removed) {
      successResponse(sc, arg0, from, {}, "intentListenerUnsubscribeResponse")
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        "Non-Existent Listener",
        "intentListenerUnsubscribeResponse",
      )
    }
  }

  onAddIntentListener(
    arg0: AddIntentListenerRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): void {
    const lr: IntentListenerRegistration = {
      appId: from.appId,
      instanceId: from.instanceId,
      intentName: arg0.payload.intent,
      contextTypes: arg0.payload.contextTypes,
      listenerUUID: sc.createUUID(),
    }

    sc.addIntentListener(lr)
    successResponse(
      sc,
      arg0,
      from,
      {
        listenerUUID: lr.listenerUUID,
      },
      "addIntentListenerResponse",
    )

    // see if this intent listener is the destination for any pending intents
    for (const x of this.pendingIntents) {
      x.accept(lr)
      if (x.complete) {
        this.pendingIntents.delete(x)
      }
    }
  }

  hasListener(
    instanceId: string,
    intentName: string,
    sc: FDC3ServerInstance,
    contextType?: string,
  ): boolean {
    return (
      sc
        .getIntentListeners()
        .find(
          (r) =>
            r.instanceId == instanceId &&
            r.intentName == intentName &&
            (contextType == undefined ||
              r.contextTypes == null ||
              r.contextTypes == undefined ||
              r.contextTypes.includes(contextType)),
        ) != null
    )
  }

  async startWithPendingIntent(
    arg0: IntentRequest,
    sc: FDC3ServerInstance,
    target: AppIdentifier,
  ): Promise<void> {
    // app exists but needs starting
    const pi = new PendingIntent(arg0, sc, this, target)
    this.pendingIntents.add(pi)
    sc.open(target.appId).then(() => {
      return undefined
    })
  }

  async raiseIntentRequestToSpecificInstance(
    arg0: IntentRequest[],
    sc: FDC3ServerInstance,
    target: FullAppIdentifier,
  ): Promise<void> {
    if (!(await sc.isAppConnected(target.instanceId))) {
      // instance doesn't exist
      return errorResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        ResolveError.TargetInstanceUnavailable,
        arg0[0].type,
      )
    }

    const requestsWithListeners = arg0.filter((r) =>
      this.hasListener(target.instanceId, r.intent, sc, r.context.type),
    )

    if (requestsWithListeners.length == 0) {
      this.createPendingIntentIfAllowed(arg0[0], sc, target)
    } else {
      // ok, deliver to the current running app.
      return forwardRequest(requestsWithListeners[0], target, sc)
    }
  }

  async createPendingIntentIfAllowed(
    ir: IntentRequest,
    sc: FDC3ServerInstance,
    target: AppIdentifier,
  ) {
    // if this app declares that it supports the intent, we'll create a pending intent
    const matchingIntents: DirectoryIntent[] = sc
      .getDirectory()
      .retrieveIntents(ir.context.type, ir.intent, undefined)
    const declared = matchingIntents.find((i) => i.appId == target.appId)

    if (declared) {
      // maybe listener hasn't been registered yet - create a pending intent
      const pi = new PendingIntent(ir, sc, this, target)
      this.pendingIntents.add(pi)
    } else {
      errorResponseId(
        sc,
        ir.requestUuid,
        ir.from,
        ResolveError.NoAppsFound,
        ir.type,
      )
    }
  }

  /**
   * Handles raiseIntent where the caller set `newInstance === false`.
   */
  async raiseIntentToExistingInstanceOnly(
    arg0: IntentRequest[],
    sc: FDC3ServerInstance,
    target: AppIdentifier,
  ): Promise<void> {
    const runningInstances = await this.retrieveRunningInstances(
      target.appId,
      sc,
    )

    if (runningInstances.length == 0) {
      return errorResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        ResolveError.TargetInstanceUnavailable,
        arg0[0].type,
      )
    }

    if (runningInstances.length == 1) {
      return this.raiseIntentRequestToSpecificInstance(
        arg0,
        sc,
        runningInstances[0],
      )
    }

    // More than one running instance - return for resolution
    const instances: AppIdentifier[] = runningInstances.map((i) => ({
      appId: i.appId,
      instanceId: i.instanceId,
    }))
    if (arg0[0].type == "raiseIntentResponse") {
      return successResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        {
          appIntent: {
            intent: { name: arg0[0].intent, displayName: arg0[0].intent },
            apps: instances,
          },
        },
        arg0[0].type,
      )
    } else {
      const appIntents: AppIntent[] = arg0.map((ir) => ({
        intent: { name: ir.intent, displayName: ir.intent },
        apps: instances,
      }))
      return successResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        { appIntents },
        arg0[0].type,
      )
    }
  }

  async raiseIntentRequestToSpecificAppId(
    arg0: IntentRequest[],
    sc: FDC3ServerInstance,
    target: AppIdentifier,
  ): Promise<void> {
    const appRecords = sc.getDirectory().retrieveAppsById(target.appId)
    if (appRecords.length == 0) {
      return errorResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        ResolveError.TargetAppUnavailable,
        arg0[0].type,
      )
    }

    // If the caller explicitly requested that an existing instance be used, never launch a new one.
    if (arg0[0].newInstance === false) {
      return this.raiseIntentToExistingInstanceOnly(arg0, sc, target)
    }

    const convertDirectoryIntentsToAppIntents = (
      intents: DirectoryIntent[],
      appId: string,
    ): AppIntent[] => {
      // group by intent name
      const intentNames = new Set(intents.map((i) => i.intentName))
      return Array.from(intentNames).map((intentName) => {
        const intentsWithName = intents.filter(
          (i) => i.intentName === intentName,
        )
        return {
          intent: { name: intentName, displayName: intentName },
          apps: intentsWithName
            .filter((i) => i.appId === appId)
            .map((i) => ({ appId: i.appId })),
        }
      })
    }

    const intentsAllHaveApps = (appIntents: AppIntent[]): boolean => {
      return appIntents.every((ai) => ai.apps.length > 0)
    }

    // in this version of the method, we always open an app as no
    // specific instance is specified.  But only if the app supports the intent.
    const context: Context = arg0[0].context
    const matchingIntents: DirectoryIntent[] = sc
      .getDirectory()
      .retrieveIntents(context.type, arg0[0].intent, undefined)
    const appIntents = convertDirectoryIntentsToAppIntents(
      matchingIntents,
      target.appId,
    )

    if (appIntents.length == 0) {
      return errorResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        ResolveError.NoAppsFound,
        arg0[0].type,
      )
    }

    if (!intentsAllHaveApps(appIntents)) {
      return errorResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        ResolveError.IntentDeliveryFailed,
        arg0[0].type,
      )
    }

    const narrowedAppIntents = await this.narrowIntents(
      arg0[0].from,
      appIntents,
      context,
      sc,
    )

    if (narrowedAppIntents.length == 1) {
      if (narrowedAppIntents[0].apps.length == 1) {
        // no running instance, single app
        const appRecords = sc.getDirectory().retrieveAppsById(target.appId)
        if (appRecords.length >= 1) {
          const ir: IntentRequest = {
            ...arg0[0],
            intent: narrowedAppIntents[0].intent.name,
          }
          return this.startWithPendingIntent(ir, sc, target)
        }
      }
    }
    // app doesn't exist
    return errorResponseId(
      sc,
      arg0[0].requestUuid,
      arg0[0].from,
      ResolveError.NoAppsFound,
      arg0[0].type,
    )
  }

  oneAppOnly(appIntent: AppIntent): boolean {
    const apps = appIntent.apps.map((a) => a.appId)
    const uniqueApps = apps.filter((v, i, a) => a.indexOf(v) === i).length
    return uniqueApps == 1
  }

  async raiseIntentToAnyApp(
    arg0: IntentRequest[],
    sc: FDC3ServerInstance,
  ): Promise<void> {
    const connectedApps = await sc.getConnectedApps()
    const matchingIntents = arg0.flatMap((i) =>
      sc.getDirectory().retrieveIntents(i.context.type, i.intent, undefined),
    )
    const matchingRegistrations = arg0.flatMap((i) =>
      sc
        .getIntentListeners()
        .filter(
          (r) =>
            r.intentName == i.intent &&
            (r.contextTypes == null ||
              r.contextTypes == undefined ||
              r.contextTypes.includes(i.context.type)),
        ),
    )
    const uniqueIntentNames = [
      ...matchingIntents.map((i) => i.intentName),
      ...matchingRegistrations.map((r) => r.intentName),
    ].filter((v, i, a) => a.indexOf(v) === i)

    const allIntents = sc.getDirectory().retrieveAllIntents()

    const appIntents: AppIntent[] = uniqueIntentNames.map((i) => {
      const directoryAppsWithIntent = matchingIntents
        .filter((mi) => mi.intentName == i)
        .map((mi) => mi.appId)
      const runningDirectoryApps = connectedApps.filter((ca) =>
        directoryAppsWithIntent.includes(ca.appId),
      )
      const appRegistrations = matchingRegistrations
        .filter((registration) => registration.intentName === i)
        .map((listener) => ({
          appId: listener.appId,
          instanceId: listener.instanceId,
          state: State.Connected,
        }))
        .filter((appRegistration) =>
          allIntents.every((intent) => intent.appId !== appRegistration.appId),
        )

      const runningApps: AppRegistration[] = [
        ...runningDirectoryApps,
        ...appRegistrations,
      ]

      return {
        intent: {
          name: i,
          displayName: i,
        },
        apps: [
          ...runningApps,
          ...directoryAppsWithIntent.map((d) => {
            return { appId: d }
          }),
        ],
      }
    })

    // Intent names can appear from live addIntentListener registrations even when
    // no directory app supports this intent+context (listeners often omit
    // contextTypes). Drop empty AppIntents so we return NoAppsFound instead of
    // sending the client a resolver with nothing to choose.
    const appIntentsWithApps = appIntents.filter((ai) => ai.apps.length > 0)

    const narrowedAppIntents = await this.narrowIntents(
      arg0[0].from,
      appIntentsWithApps,
      arg0[0].context,
      sc,
    )

    if (
      narrowedAppIntents.length == 0 ||
      narrowedAppIntents.every((ai) => ai.apps.length == 0)
    ) {
      // nothing can resolve the intent, fail
      return errorResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        ResolveError.NoAppsFound,
        arg0[0].type,
      )
    }

    if (narrowedAppIntents.length == 1) {
      const theAppIntent = narrowedAppIntents[0]
      if (this.oneAppOnly(theAppIntent)) {
        const instanceCount = theAppIntent.apps.filter(
          (a) => a.instanceId,
        ).length
        const ir: IntentRequest = {
          ...arg0[0],
          intent: narrowedAppIntents[0].intent.name,
        }
        const newInstance = arg0[0].newInstance
        const runningInstance = theAppIntent.apps.find((a) => a.instanceId)

        if (newInstance === true) {
          // Caller requested a new instance - always launch one
          return this.startWithPendingIntent(ir, sc, {
            appId: theAppIntent.apps[0].appId,
          })
        } else if (newInstance === false) {
          // Caller requires an existing instance - never launch a new one
          if (runningInstance && isFullAppIdentifier(runningInstance)) {
            return forwardRequest(ir, runningInstance, sc)
          }
          return errorResponseId(
            sc,
            arg0[0].requestUuid,
            arg0[0].from,
            ResolveError.TargetInstanceUnavailable,
            arg0[0].type,
          )
        }

        // Default behavior (newInstance undefined)
        if (instanceCount == 1 && isFullAppIdentifier(theAppIntent.apps[0])) {
          // app is running
          return forwardRequest(ir, theAppIntent.apps[0], sc)
        } else if (instanceCount == 0) {
          return this.startWithPendingIntent(ir, sc, theAppIntent.apps[0])
        }
      }
    }

    if (arg0[0].type == "raiseIntentResponse") {
      // raise intent
      return successResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        {
          appIntent: narrowedAppIntents[0],
        },
        arg0[0].type,
      )
    } else {
      // raise intent for context
      return successResponseId(
        sc,
        arg0[0].requestUuid,
        arg0[0].from,
        { appIntents: narrowedAppIntents },
        arg0[0].type,
      )
    }
  }

  async raiseIntentRequest(
    arg0: RaiseIntentRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const reqMeta = arg0.payload.metadata ?? {}
    const intentRequest: IntentRequest = {
      context: arg0.payload.context,
      from,
      intent: arg0.payload.intent,
      requestUuid: arg0.meta.requestUuid,
      type: "raiseIntentResponse",
      newInstance: arg0.payload.newInstance ?? undefined,
      appProvidedMetadata: {
        traceId: reqMeta.traceId,
        signature: reqMeta.signature,
        antiReplay: reqMeta.antiReplay,
        custom: reqMeta.custom,
      },
    }

    const target = arg0.payload.app
    if (target) {
      if (isFullAppIdentifier(target)) {
        return this.raiseIntentRequestToSpecificInstance(
          [intentRequest],
          sc,
          target,
        )
      } else if (target.appId) {
        return this.raiseIntentRequestToSpecificAppId(
          [intentRequest],
          sc,
          target,
        )
      } else {
        //invalid target
        this.log(
          "Received an invalid target argument for raiseIntent",
          target,
          arg0,
        )
        return errorResponseId(
          sc,
          arg0.meta.requestUuid,
          from,
          ResolveError.TargetAppUnavailable,
          "raiseIntentResponse",
        )
      }
    } else {
      //No target
      return this.raiseIntentToAnyApp([intentRequest], sc)
    }
  }

  async raiseIntentForContextRequest(
    arg0: RaiseIntentForContextRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    // dealing with a specific instance of an app
    const mappedIntents = sc
      .getDirectory()
      .retrieveIntents(arg0.payload.context.type, undefined, undefined)
    const uniqueIntentNames = mappedIntents.filter(
      (v, i, a) => a.findIndex((v2) => v2.intentName == v.intentName) == i,
    )
    const rifcMeta = arg0.payload.metadata ?? {}
    const possibleIntentRequests: IntentRequest[] = uniqueIntentNames.map(
      (i) => {
        return {
          context: arg0.payload.context,
          from,
          intent: i.intentName,
          requestUuid: arg0.meta.requestUuid,
          type: "raiseIntentForContextResponse",
          newInstance: arg0.payload.newInstance ?? undefined,
          appProvidedMetadata: {
            traceId: rifcMeta.traceId,
            signature: rifcMeta.signature,
            antiReplay: rifcMeta.antiReplay,
            custom: rifcMeta.custom,
          },
        }
      },
    )

    if (possibleIntentRequests.length == 0) {
      return errorResponseId(
        sc,
        arg0.meta.requestUuid,
        from,
        ResolveError.NoAppsFound,
        "raiseIntentForContextResponse",
      )
    }

    const target = arg0.payload.app
    if (target) {
      if (isFullAppIdentifier(target)) {
        return this.raiseIntentRequestToSpecificInstance(
          possibleIntentRequests,
          sc,
          target,
        )
      } else if (target.appId) {
        return this.raiseIntentRequestToSpecificAppId(
          possibleIntentRequests,
          sc,
          target,
        )
      } else {
        //invalid target
        this.log(
          "Received an invalid target argument for raiseIntentForContext",
          target,
          arg0,
        )
        return errorResponseId(
          sc,
          arg0.meta.requestUuid,
          from,
          ResolveError.TargetAppUnavailable,
          "raiseIntentForContextResponse",
        )
      }
    } else {
      //No target
      return this.raiseIntentToAnyApp(possibleIntentRequests, sc)
    }
  }

  async findIntentsByContextRequest(
    r: FindIntentsByContextRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const { context, resultType } = r.payload

    const apps1 = sc
      .getDirectory()
      .retrieveIntents(context?.type, undefined, resultType)

    // fold apps so same intents aren't duplicated
    const apps2: AppIntent[] = []
    //don't use foreach as the handling function is async and needs to process serially
    for (let index = 0; index < apps1.length; index++) {
      const a1 = apps1[index]
      const existing = apps2.find((a2) => a2.intent.name == a1.intentName)
      const runningInstances = await this.retrieveRunningInstances(a1.appId, sc)
      if (existing) {
        existing.apps.push({ appId: a1.appId })
        runningInstances.forEach((ri) =>
          existing.apps.push({ appId: a1.appId, instanceId: ri.instanceId }),
        )
      } else {
        const appIntent: AppIntent = {
          intent: {
            name: a1.intentName,
            displayName: a1.displayName ?? a1.intentName,
          },
          apps: [
            {
              appId: a1.appId,
            },
          ],
        }
        runningInstances.forEach((ri) =>
          appIntent.apps.push({ appId: a1.appId, instanceId: ri.instanceId }),
        )
        apps2.push(appIntent)
      }
    }

    successResponse(
      sc,
      r,
      from,
      {
        appIntents: apps2,
      },
      "findIntentsByContextResponse",
    )
  }

  async findIntentRequest(
    r: FindIntentRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const { intent, context, resultType } = r.payload

    // listeners for connected applications
    const apps2 = (await this.retrieveListeners(intent, sc)).map((lr) => {
      return {
        appId: lr.appId,
        instanceId: lr.instanceId,
      }
    }) as AppIdentifier[]

    // directory entries
    const apps1 = sc
      .getDirectory()
      .retrieveApps(context?.type, intent, resultType)
      .map((a) => {
        return {
          appId: a.appId,
        }
      })

    //combine the lists, no need to de-duplicate as we should return both a directory record with just appId + any instance with appId/instanceId
    const finalApps = [...apps1, ...apps2]

    // just need this for the (deprecated) display name
    const allMatchingIntents = sc
      .getDirectory()
      .retrieveIntents(context?.type, intent, resultType)
    const displayName =
      allMatchingIntents.length > 0
        ? allMatchingIntents[0].displayName
        : undefined

    successResponse(
      sc,
      r,
      from,
      {
        appIntent: {
          intent: {
            name: intent,
            displayName,
          },
          apps: finalApps,
        },
      },
      "findIntentResponse",
    )
  }

  async retrieveListeners(
    intentName: string | undefined,
    sc: FDC3ServerInstance,
  ): Promise<IntentListenerRegistration[]> {
    const activeApps = await sc.getConnectedApps()
    const matching = sc
      .getIntentListeners()
      .filter((r) => r.intentName == intentName)
    const active = matching.filter((r) =>
      activeApps.find((a) => a.instanceId == r.instanceId),
    )
    return active
  }

  async retrieveRunningInstances(appId: string, sc: FDC3ServerInstance) {
    const activeApps = await sc.getConnectedApps()
    const filteredApps = activeApps.filter((a) => a.appId === appId)
    return filteredApps
  }

  async handleEvent(): Promise<void> {}
}

import { LogFunction, MessageHandler } from "../MessageHandler"
import { FDC3ServerInstance } from "../../FDC3ServerInstance"
import { InstanceID, State, ReceivableMessage } from "../../AppRegistration"
import { DirectoryApp } from "../../directory/DirectoryInterface"
import {
  ResolveError,
  AppIdentifier,
  AppMetadata,
  ImplementationMetadata,
} from "@finos/fdc3-standard"
import { CloseError } from "@finos/fdc3-standard-v3"
import { BrowserTypes } from "@finos/fdc3-schema-v3"
import { errorResponse, FullAppIdentifier, successResponse } from "./support"
import {
  AgentResponseMessage,
  AppRequestMessage,
  CloseRequest,
  GetInfoRequest,
  isAddContextListenerRequest,
  isCloseRequest,
  isFindInstancesRequest,
  isGetAppMetadataRequest,
  isGetInfoRequest,
  isOpenRequest,
  isWebConnectionProtocol4ValidateAppIdentity,
} from "@finos/fdc3-schema-v3/dist/generated/api/BrowserTypes"
import { AppState, PendingApp } from "../../PendingApp"

type AddContextListenerRequest = BrowserTypes.AddContextListenerRequest
type FindInstancesRequest = BrowserTypes.FindInstancesRequest
type GetAppMetadataRequest = BrowserTypes.GetAppMetadataRequest
type OpenRequest = BrowserTypes.OpenRequest
type WebConnectionProtocol4ValidateAppIdentity =
  BrowserTypes.WebConnectionProtocol4ValidateAppIdentity
type WebConnectionProtocol5ValidateAppIdentityFailedResponse =
  BrowserTypes.WebConnectionProtocol5ValidateAppIdentityFailedResponse
type WebConnectionProtocol5ValidateAppIdentitySuccessResponse =
  BrowserTypes.WebConnectionProtocol5ValidateAppIdentitySuccessResponse

export class OpenHandler implements MessageHandler {
  readonly timeoutMs: number
  private readonly log: LogFunction

  constructor(timeoutMs: number, log?: LogFunction) {
    this.timeoutMs = timeoutMs
    this.log = log ?? (() => {})
  }

  shutdown(): void {}

  async accept(
    msg: ReceivableMessage,
    sc: FDC3ServerInstance,
    uuid: InstanceID,
  ): Promise<void> {
    if (isWebConnectionProtocol4ValidateAppIdentity(msg)) {
      return this.handleValidate(
        msg as WebConnectionProtocol4ValidateAppIdentity,
        sc,
        uuid,
      )
    } else if (isAddContextListenerRequest(msg)) {
      //handle context listener adds for pending applications (i.e. opened but awaiting context listener addition to deliver context)
      //  additional handling is performed in BroadcastHandler
      return this.handleAddContextListener(
        msg as AddContextListenerRequest,
        sc,
        uuid,
      )
    } else {
      const from = sc.getInstanceDetails(uuid)
      if (from) {
        try {
          if (isOpenRequest(msg)) {
            return this.open(msg, sc, from)
          } else if (isFindInstancesRequest(msg)) {
            return this.findInstances(msg, sc, from)
          } else if (isGetAppMetadataRequest(msg)) {
            return this.getAppMetadata(msg, sc, from)
          } else if (isGetInfoRequest(msg)) {
            return this.getInfo(msg, sc, from)
          } else if (isCloseRequest(msg)) {
            return this.close(msg, sc, from)
          }
        } catch (e) {
          const responseType = (msg.type as string).replace(
            new RegExp("Request$"),
            "Response",
          ) as AgentResponseMessage["type"]
          errorResponse(
            sc,
            msg as unknown as AppRequestMessage,
            from,
            (e as Error).message ?? e,
            responseType,
          )
        }
      } else {
        this.log("Received message from unknown source, ignoring", msg, uuid)
      }
    }
  }

  /**
   * This deals with sending pending context to listeners of newly-opened apps.
   */
  handleAddContextListener(
    arg0: AddContextListenerRequest,
    sc: FDC3ServerInstance,
    from: InstanceID,
  ): void {
    const pendingOpen = sc.getPendingApp(from) as PendingApp | undefined
    if (pendingOpen) {
      const contextType = arg0.payload.contextType
      const contextTypes = arg0.payload.contextTypes
      if (
        pendingOpen.context &&
        pendingOpen.state == AppState.DeliveringContext
      ) {
        const typeMatches =
          contextType == pendingOpen.context.type ||
          contextType == undefined ||
          (contextTypes != undefined &&
            contextTypes.includes(pendingOpen.context.type))
        if (typeMatches) {
          // ok, we can deliver to this listener
          const appMeta = pendingOpen.appProvidedMetadata
          const message = {
            meta: {
              eventUuid: sc.createUUID(),
              timestamp: new Date(),
            },
            type: "broadcastEvent" as const,
            payload: {
              channelId: null as string | null,
              context: pendingOpen.context,
              metadata: {
                source: {
                  appId: pendingOpen.source.appId,
                  instanceId: pendingOpen.source.instanceId,
                },
                timestamp: new Date(),
                traceId: appMeta.traceId ?? sc.createUUID(),
                ...(appMeta.signature !== undefined && {
                  signature: appMeta.signature,
                }),
                ...(appMeta.antiReplay !== undefined && {
                  antiReplay: appMeta.antiReplay,
                }),
                ...(appMeta.custom !== undefined && {
                  custom: appMeta.custom,
                }),
              },
            },
          }

          pendingOpen.setDone()
          sc.removePendingApp(from)
          sc.post(message, from)
        }
      }
    }
  }

  filterPublicDetails(appD: DirectoryApp, appID: AppIdentifier): AppMetadata {
    return {
      appId: appD.appId,
      name: appD.name,
      version: appD.version,
      title: appD.title,
      tooltip: appD.tooltip,
      description: appD.description,
      icons: appD.icons,
      screenshots: appD.screenshots,
      instanceId: appID.instanceId,
    }
  }

  getAppMetadata(
    arg0: GetAppMetadataRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): void {
    const appID = arg0.payload.app
    const details = sc.getDirectory().retrieveAppsById(appID.appId)
    if (details.length > 0) {
      successResponse(
        sc,
        arg0,
        from,
        {
          appMetadata: this.filterPublicDetails(details[0], appID),
        },
        "getAppMetadataResponse",
      )
    } else {
      errorResponse(
        sc,
        arg0,
        from,
        ResolveError.TargetAppUnavailable,
        "getAppMetadataResponse",
      )
    }
  }

  async findInstances(
    arg0: FindInstancesRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const appId = arg0.payload.app.appId
    const openApps = await sc.getConnectedApps()
    const matching = openApps
      .filter((a) => a.appId == appId)
      .map((a) => {
        return {
          appId: a.appId,
          instanceId: a.instanceId,
        }
      })
    successResponse(
      sc,
      arg0,
      from,
      {
        appIdentifiers: matching,
      },
      "findInstancesResponse",
    )
  }

  async open(
    arg0: OpenRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const toOpen = arg0.payload.app
    const context = arg0.payload.context

    try {
      const reqMeta = arg0.payload.metadata ?? {}
      const uuid = await sc.open(toOpen.appId)
      if (context) {
        sc.setPendingApp(
          uuid,
          new PendingApp(sc, arg0, context, from, this.timeoutMs, {
            traceId: reqMeta.traceId,
            signature: reqMeta.signature,
            antiReplay: reqMeta.antiReplay,
            custom: reqMeta.custom,
          }),
        )
      } else {
        // No context: resolve as soon as the app launches; do not wait for FDC3.
        successResponse(
          sc,
          arg0,
          from,
          {
            appIdentifier: {
              appId: toOpen.appId,
              instanceId: uuid,
            },
          },
          "openResponse",
        )
      }
    } catch (e) {
      errorResponse(sc, arg0, from, (e as Error).message ?? e, "openResponse")
    }
  }

  async getInfo(
    arg0: GetInfoRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    const implMetadata: ImplementationMetadata = this.getImplementationMetadata(
      sc,
      {
        appId: from.appId,
        instanceId: from.instanceId,
      },
      from,
    )
    successResponse(
      sc,
      arg0,
      from,
      {
        implementationMetadata: implMetadata,
      },
      "getInfoResponse",
    )
  }

  async close(
    arg0: CloseRequest,
    sc: FDC3ServerInstance,
    from: FullAppIdentifier,
  ): Promise<void> {
    if (!(await sc.isAppConnected(from.instanceId))) {
      errorResponse(
        sc,
        arg0,
        from,
        CloseError.ErrorOnClose,
        "closeResponse",
      )
      return
    }

    try {
      await sc.close(from.instanceId)
    } catch (e) {
      errorResponse(
        sc,
        arg0,
        from,
        (e as Error).message ?? CloseError.ErrorOnClose,
        "closeResponse",
      )
    }
  }

  getImplementationMetadata(
    sc: FDC3ServerInstance,
    appIdentity: AppIdentifier,
    from?: FullAppIdentifier,
  ) {
    const appMetadata = this.filterPublicDetails(
      sc.getDirectory().retrieveAppsById(appIdentity.appId)[0],
      appIdentity,
    )
    const details = from
      ? sc.getInstanceDetails(from.instanceId)
      : sc.getInstanceDetails(appIdentity.instanceId ?? "")
    return {
      provider: sc.provider(),
      providerVersion: sc.providerVersion(),
      fdc3Version: details?.fdc3Version ?? sc.fdc3Version(),
      optionalFeatures: {
        DesktopAgentBridging: false,
        OriginatingAppMetadata: true,
        UserChannelMembershipAPIs: true,
      },
      appMetadata: appMetadata,
    }
  }

  async handleValidate(
    arg0: WebConnectionProtocol4ValidateAppIdentity,
    sc: FDC3ServerInstance,
    from: InstanceID,
  ): Promise<void> {
    const responseMeta = {
      connectionAttemptUuid: arg0.meta.connectionAttemptUuid,
      timestamp: new Date(),
    }

    const returnError = () => {
      const msg: WebConnectionProtocol5ValidateAppIdentityFailedResponse = {
        meta: responseMeta,
        type: "WCP5ValidateAppIdentityFailedResponse",
        payload: {
          message: "App Instance not found",
        },
      }
      sc.post(msg, from)
    }

    const returnSuccess = (appId: string, instanceId: string) => {
      const implMetadata: ImplementationMetadata =
        this.getImplementationMetadata(
          sc,
          { appId, instanceId },
          { appId, instanceId },
        )
      const msg: WebConnectionProtocol5ValidateAppIdentitySuccessResponse = {
        meta: responseMeta,
        type: "WCP5ValidateAppIdentityResponse",
        payload: {
          appId: appId,
          instanceId: instanceId,
          instanceUuid: from,
          implementationMetadata: implMetadata,
        },
      }
      sc.post(msg, instanceId)
    }

    if (arg0.payload.instanceUuid) {
      // existing app reconnecting
      this.log("App attempting to reconnect:", arg0.payload.instanceUuid)
      const appIdentity = sc.getInstanceDetails(arg0.payload.instanceUuid)

      if (appIdentity) {
        // in this case, the app is reconnecting, so let's just re-assign the identity
        this.log(
          `Reassigned existing identity, appId: `,
          appIdentity.appId,
          ", instanceId",
          arg0.payload.instanceUuid,
        )
        sc.setInstanceDetails(from, appIdentity)
        sc.setAppState(from, State.Connected)
        return returnSuccess(appIdentity.appId, appIdentity.instanceId)
      } else {
        //we didn't find the identity, assign a new one
        this.log(
          "Existing identity not found for, assigning a new one: ",
          arg0.payload.instanceUuid,
        )
      }
    }

    // we need to assign an identity to this app - this should have been generated when it was launched
    const appIdentity = sc.getInstanceDetails(from)
    if (appIdentity) {
      sc.setAppState(appIdentity.instanceId, State.Connected)
      returnSuccess(appIdentity.appId, appIdentity.instanceId)

      // make sure, if the opener is listening for this app to open, then it gets informed
      const pendingOpen = sc.getPendingApp(from) as PendingApp | undefined
      if (pendingOpen) {
        if (pendingOpen.state == AppState.Opening) {
          pendingOpen.setOpened(appIdentity)
        }
      }
    } else {
      returnError()
    }
  }

  async handleEvent(): Promise<void> {
    // no-op
  }
}

import { Directory, DirectoryApp, DirectoryIntent } from "./DirectoryInterface"

export function genericResultTypeSame(
  real: string | undefined,
  required: string | undefined,
) {
  if (required == undefined) {
    return true
  } else if (real == required) {
    return true
  } else if (real == undefined) {
    return false // required is not undefined, so asking for something
  } else if (real.startsWith("channel<") && required == "channel") {
    return true
  } else {
    return false
  }
}

/**
 * Basic directory implementation that allows queries over a set of apps.
 */
export class BasicDirectory implements Directory {
  allApps: DirectoryApp[]

  constructor(apps: DirectoryApp[]) {
    this.allApps = apps
  }

  private intentMatches(
    i: DirectoryIntent,
    contextType: string | undefined,
    intentName: string | undefined,
    resultType: string | undefined,
  ): boolean {
    const out =
      (intentName == undefined || i.intentName == intentName) &&
      (contextType == undefined || (i.contexts ?? []).includes(contextType)) &&
      genericResultTypeSame(i.resultType, resultType)
    return out
  }

  private retrieveIntentsForApp(a: DirectoryApp): DirectoryIntent[] {
    const lf = a.interop?.intents?.listensFor ?? {}
    const lfa = Object.entries(lf)
    const lfAugmented = lfa.map(([key, value]) => {
      return {
        intentName: key,
        ...value,
        appId: a.appId,
      }
    })
    return lfAugmented
  }

  retrieveAllIntents(): DirectoryIntent[] {
    const allIntents = this.retrieveAllApps().flatMap((a) =>
      this.retrieveIntentsForApp(a),
    )

    return allIntents
  }

  retrieveIntents(
    contextType: string | undefined,
    intentName: string | undefined,
    resultType: string | undefined,
  ): DirectoryIntent[] {
    const matchingIntents = this.retrieveAllIntents().filter((i) =>
      this.intentMatches(i, contextType, intentName, resultType),
    )
    return matchingIntents
  }

  retrieveApps(
    contextType: string | undefined,
    intentName?: string | undefined,
    resultType?: string | undefined,
  ): DirectoryApp[] {
    const result = this.retrieveAllApps().filter(
      (a) =>
        this.retrieveIntentsForApp(a).filter((i) =>
          this.intentMatches(i, contextType, intentName, resultType),
        ).length > 0,
    )

    return result
  }

  retrieveAppsById(appId: string): DirectoryApp[] {
    return this.retrieveAllApps().filter((a) => a.appId == appId)
  }

  retrieveAllApps(): DirectoryApp[] {
    return this.allApps
  }
}
